import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC721 } from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import { IERC1155 } from "@openzeppelin/contracts/token/ERC1155/IERC1155.sol";

/**
 * @title ExchangeCommitBase
 *
 * @notice Shared commit-related helper functions used by both ExchangeCommitFacet and any facet
 * that needs to atomically commit on the buyer's behalf (e.g. orchestration that combines
 * commit with redeem).
 *
 * Centralizes:
 *  - {commitToOfferInternal} — encumbers funds, creates the exchange/voucher and issues the NFT.
 *  - {commitToStaticOfferShared} / {commitToConditionalOfferShared} — wrappers used by both
 *    public {commitToOffer}/{commitToConditionalOffer} and the orchestration commit-and-redeem
 *    variants, so the validation+commit logic exists in one place.
 *  - {prepareOfferForCommit} — verifies the FullOffer signature, creates the offer + group on
 *    first use, and deposits the offer creator's funds. Reused by {createOfferAndCommit} and
 *    its commit-and-redeem orchestration counterpart.
 *  - {verifyOffer} — validates an EIP-712 / ERC1271 signature over a FullOffer.
 *  - {authorizeCommit} — token-gating checks for conditional offers.
 *  - {addSellerParametersToBuyerOffer} — applies seller-side parameters to a buyer-created offer.
 *  - DR-fee collection and condition-range validation.
 */
contract ExchangeCommitBase is BuyerBase, OfferBase, GroupBase, IBosonExchangeEvents {
    /**
     * @notice Validates a static, non-conditional offer and commits to it.
     *
     * Shared body of {commitToOffer} and the orchestration {commitToOfferAndRedeemVoucher}.
     * The caller is responsible for any additional access control (e.g. verifying the
     * committer is non-zero) and for setting modifiers like nonReentrant / pause regions.
     *
     * Reverts if:
     * - The offer's price type is not Static
     * - The offer is associated with a group that has a non-empty condition
     *   (caller should use the conditional-offer entry point instead)
     * - Any reason that {commitToOfferInternal} reverts
     *
     * @param _committer - the buyer's wallet (or seller assistant for buyer-created offers)
     * @param _offerId - the id of the offer to commit to
     * @param _skipVoucher - skip the voucher NFT mint and voucherCount increment. Pass true
     *                       only from atomic commit-and-redeem orchestration paths.
     * @return exchangeId - the id of the newly created exchange
     */
    function commitToStaticOfferShared(
        address payable _committer,
        uint256 _offerId,
        bool _skipVoucher
    ) internal returns (uint256 exchangeId) {
        Offer storage offer = getValidOffer(_offerId);
        if (offer.priceType != PriceType.Static) revert InvalidPriceType();

        // Atomic commit-and-redeem orchestration paths skip the voucher mint+burn
        // and the buyer-ownership check on redeem. That is only safe when
        // `_committer == _msgSender()` is the on-chain buyer of the new exchange,
        // which holds for seller-created offers (buyerId = getValidBuyer(_committer))
        // but NOT for buyer-created ones (buyerId = offer.buyerId, possibly a third
        // party — letting any caller siphon the seller's deposit + bundled twins).
        if (_skipVoucher && offer.creator != OfferCreator.Seller) revert OfferCreatorMustBeSeller();

        // For there to be a condition, there must be a group.
        (bool exists, uint256 groupId) = getGroupIdByOffer(offer.id);
        if (exists) {
            // Get the condition
            Condition storage condition = fetchCondition(groupId);
            // Conditional offers must use the conditional-offer entry point.
            if (condition.method != EvaluationMethod.None) revert GroupHasCondition();
        }

        return commitToOfferInternal(_committer, offer, 0, false, _skipVoucher);
    }

    /**
     * @notice Validates a token-gated (conditional) static offer and commits to it.
     *
     * Shared body of {commitToConditionalOffer} and the orchestration
     * {commitToConditionalOfferAndRedeemVoucher}. Stores the condition snapshot on the
     * exchange so {getReceipt} can return it.
     *
     * Reverts if:
     * - The offer's price type is not Static
     * - The offer is buyer-created and `_allowBuyerCreated` is false
     * - The offer is not associated with a group / has no condition
     * - The token id is not in the condition's range
     * - The buyer does not satisfy the condition (or has reached `maxCommits`)
     * - Any reason that {commitToOfferInternal} reverts
     *
     * @param _committer - the committer's wallet (buyer for seller-created offers, seller assistant for buyer-created)
     * @param _offerId - the id of the offer to commit to
     * @param _tokenId - the id of the conditional token used to satisfy the condition
     * @param _allowBuyerCreated - if false, reverts with OfferCreatorMustBeSeller for buyer-created offers
     * @param _skipVoucher - skip the voucher NFT mint and voucherCount increment. Pass true
     *                       only from atomic commit-and-redeem orchestration paths.
     * @return exchangeId - the id of the newly created exchange
     */
    function commitToConditionalOfferShared(
        address payable _committer,
        uint256 _offerId,
        uint256 _tokenId,
        bool _allowBuyerCreated,
        bool _skipVoucher
    ) internal returns (uint256 exchangeId) {
        Offer storage offer = getValidOffer(_offerId);
        if (offer.priceType != PriceType.Static) revert InvalidPriceType();

        // For there to be a condition, there must be a group.
        (bool exists, uint256 groupId) = getGroupIdByOffer(offer.id);

        // Make sure the group exists
        if (!exists) revert NoSuchGroup();

        // Get the condition
        Condition storage condition = fetchCondition(groupId);

        // Make sure the tokenId is in range
        validateConditionRange(condition, _tokenId);

        address buyerAddress;
        if (offer.creator == OfferCreator.Buyer) {
            if (!_allowBuyerCreated) revert OfferCreatorMustBeSeller();
            (, Buyer storage buyer) = fetchBuyer(offer.buyerId);
            buyerAddress = buyer.wallet;

            // For buyer-created offers, group sellerId is originally 0, so update it from the offer.
            protocolEntities().groups[groupId].sellerId = offer.sellerId;
        } else {
            buyerAddress = _committer;
        }
        authorizeCommit(buyerAddress, condition, groupId, _tokenId, _offerId);

        exchangeId = commitToOfferInternal(_committer, offer, 0, false, _skipVoucher);

        // Snapshot the condition for getReceipt
        protocolLookups().exchangeCondition[exchangeId] = condition;
    }

    /**
     * @notice Verifies a FullOffer signature, creates the offer (and a group when the offer
     * carries a non-empty condition) on first use, and deposits the offer creator's funds
     * if `_fullOffer.useDepositedFunds` is false.
     *
     * Shared body of {createOfferAndCommit} and the orchestration {createOfferCommitAndRedeem}.
     * The commit step itself is left to the caller so each entry point can keep its own
     * modifier set (e.g. avoiding double nonReentrant guards).
     *
     * Reverts if:
     * - The offer signature is invalid (see {verifyOffer})
     * - The offer was previously voided
     * - Any reason that {createOfferInternal} or {createGroupInternal} reverts
     *
     * @param _fullOffer - the fully populated struct describing the offer to create or look up
     * @param _offerCreator - the address that signed the offer (must match the offer's seller or buyer)
     * @param _signature - signature of the offer creator over the FullOffer hash
     * @return offerId - the id of the (new or existing) offer ready to be committed to
     */
    function prepareOfferForCommit(
        BosonTypes.FullOffer calldata _fullOffer,
        address _offerCreator,
        bytes calldata _signature
    ) internal returns (uint256 offerId) {
        bytes32 offerHash;
        // verify signature and potential cancellation
        (offerHash, offerId) = verifyOffer(_fullOffer, _offerCreator, _signature);

        // create an offer
        if (offerId == 0) {
            offerId = createOfferInternal(
                _fullOffer.offer,
                _fullOffer.offerDates,
                _fullOffer.offerDurations,
                _fullOffer.drParameters,
                _fullOffer.agentId,
                _fullOffer.feeLimit,
                false
            );
            protocolLookups().offerIdByHash[offerHash] = offerId;

            if (_fullOffer.condition.method != BosonTypes.EvaluationMethod.None) {
                // Construct new group; group id of 0 is ignored by createGroupInternal.
                Group memory group;
                group.sellerId = _fullOffer.offer.sellerId;
                group.offerIds = new uint256[](1);
                group.offerIds[0] = offerId;

                // Create group and update structs values to represent true state
                createGroupInternal(group, _fullOffer.condition, false);
            }
        }

        // Deposit other committer's funds if needed
        if (!_fullOffer.useDepositedFunds) {
            uint256 offerCreatorId;
            uint256 offerCreatorAmount;
            if (_fullOffer.offer.creator == OfferCreator.Buyer) {
                // Buyer-created offer: the offer creator pre-funds the price.
                offerCreatorId = _fullOffer.offer.buyerId;
                offerCreatorAmount = _fullOffer.offer.price;
            } else {
                // Seller-created offer: the offer creator pre-funds the seller deposit.
                offerCreatorId = _fullOffer.offer.sellerId;
                offerCreatorAmount = _fullOffer.offer.sellerDeposit;
            }

            // transferFundsIn discards the queue slot internally when
            // offerCreatorAmount == 0, so the off-chain caller can supply a
            // queue whose layout is independent of runtime amounts.
            transferFundsIn(_fullOffer.offer.exchangeToken, _offerCreator, offerCreatorAmount);

            if (offerCreatorAmount > 0) {
                increaseAvailableFunds(offerCreatorId, _fullOffer.offer.exchangeToken, offerCreatorAmount);
                emit IBosonFundsBaseEvents.FundsDeposited(
                    offerCreatorId,
                    _offerCreator,
                    _fullOffer.offer.exchangeToken,
                    offerCreatorAmount
                );
            }
        } else {
            // useDepositedFunds=true: offer-creator pull is bypassed entirely.
            // Discard the queue slot reserved for it so the queue layout stays
            // uniform across this flag.
            TokenTransferAuthorizationLib.discardNext();
        }
    }

    /**
     * @notice Verifies an offer and its signature.
     *
     * Reverts if:
     * - Offer is not valid
     * - Offer has been voided
     * - Signature is invalid. Refer to EIP712Lib.verify for details
     */
    function verifyOffer(
        BosonTypes.FullOffer calldata _fullOffer,
        address _offerCreator,
        bytes calldata _signature
    ) internal returns (bytes32 offerHash, uint256 offerId) {
        // `_fullOffer.offer.voided` is checked in createOfferInternal
        if (
            _fullOffer.offer.id != 0 ||
            _fullOffer.offer.royaltyInfo.length != 1 ||
            _fullOffer.offer.priceType != BosonTypes.PriceType.Static
        ) revert InvalidOffer();

        offerHash = getOfferHashInternal(_fullOffer);

        offerId = protocolLookups().offerIdByHash[offerHash];

        // Check if the non-listed offer has been voided via `voidOffer`
        // Does not apply to already listed offers, with `voided` set to true
        if (offerId == VOIDED_OFFER_ID) {
            // Offer is voided
            revert OfferHasBeenVoided();
        }

        // Verify the _offerCreator's address matches the offer's creator role and ID
        if (_fullOffer.offer.creator == OfferCreator.Seller) {
            (, uint256 sellerId) = getSellerIdByAssistant(_offerCreator);
            if (sellerId != _fullOffer.offer.sellerId) {
                revert NotAssistant();
            }
        } else if (_fullOffer.offer.creator == OfferCreator.Buyer) {
            uint256 buyerId = getValidBuyer(payable(_offerCreator));
            if (buyerId != _fullOffer.offer.buyerId) {
                revert NotBuyerWallet();
            }
        }

        if (offerId == 0) EIP712Lib.verify(_offerCreator, offerHash, _signature);
    }

    /**
     * @notice Commits to an offer (shared body of commitToOffer / commitToConditionalOffer / commitToBuyerOffer / onPremintedVoucherTransferred).
     *
     * @param _committer - committer's address (buyer for seller-created offers, seller for buyer-created offers)
     * @param _offer - storage pointer to the offer
     * @param _exchangeId - the id of the exchange (only meaningful for preminted)
     * @param _isPreminted - whether the offer is preminted
     * @param _skipVoucher - when true, skip both the bosonVoucher.issueVoucher() call and the
     *                       voucherCount[buyerId]++ write. Used by atomic commit-and-redeem
     *                       orchestration paths that immediately burn the voucher again.
     * @return exchangeId - the id of the exchange
     */
    function commitToOfferInternal(
        address payable _committer,
        Offer storage _offer,
        uint256 _exchangeId,
        bool _isPreminted,
        bool _skipVoucher
    ) internal returns (uint256) {
        uint256 _offerId = _offer.id;
        // Make sure offer is currently available; sold-out is checked later for non-preminted offers
        OfferDates storage offerDates = fetchOfferDates(_offerId);
        if (block.timestamp < offerDates.validFrom) revert OfferNotAvailable();
        if (block.timestamp > offerDates.validUntil) revert OfferHasExpired();

        if (!_isPreminted) {
            // For non-preminted offers, quantityAvailable must be greater than zero, since it gets decremented
            if (_offer.quantityAvailable == 0) revert OfferSoldOut();

            // Get next exchange id for non-preminted offers
            _exchangeId = protocolCounters().nextExchangeId++;
        } else {
            // Exchange must not exist already
            (bool exists, ) = fetchExchange(_exchangeId);

            if (exists) revert ExchangeAlreadyExists();
        }

        uint256 buyerId;

        if (_offer.creator == OfferCreator.Buyer) {
            // For buyer-created offers, buyer ID is stored in the offer
            buyerId = _offer.buyerId;
            // Encumber seller deposit (seller is committing)
            encumberFunds(_offerId, _offer.sellerId, _offer.sellerDeposit, _isPreminted, _offer.priceType);
        } else {
            buyerId = getValidBuyer(_committer);
            // Encumber buyer payment (buyer is committing)
            encumberFunds(_offerId, buyerId, _offer.price, _isPreminted, _offer.priceType);
        }

        // Create and store a new exchange
        Exchange storage exchange = protocolEntities().exchanges[_exchangeId];
        exchange.id = _exchangeId;
        exchange.offerId = _offerId;
        exchange.buyerId = buyerId;
        exchange.state = ExchangeState.Committed;

        // Handle DR fee collection
        {
            // Get dispute resolution terms to get the dispute resolver ID
            DisputeResolutionTerms storage disputeTerms = fetchDisputeResolutionTerms(_offerId);

            uint256 drFeeAmount = disputeTerms.feeAmount;

            // Handle DR fee collection if fee exists
            if (drFeeAmount > 0) {
                handleDRFeeCollection(_exchangeId, _offer, disputeTerms, drFeeAmount);
                exchange.mutualizerAddress = disputeTerms.mutualizerAddress;
            }
        }

        // Create and store a new voucher
        Voucher storage voucher = protocolEntities().vouchers[_exchangeId];
        voucher.committedDate = block.timestamp;

        // Operate in a block to avoid "stack too deep" error
        {
            // Determine the time after which the voucher can be redeemed
            uint256 startDate = (block.timestamp >= offerDates.voucherRedeemableFrom)
                ? block.timestamp
                : offerDates.voucherRedeemableFrom;

            // Determine the time after which the voucher can no longer be redeemed
            voucher.validUntilDate = (offerDates.voucherRedeemableUntil > 0)
                ? offerDates.voucherRedeemableUntil
                : startDate + fetchOfferDurations(_offerId).voucherValid;
        }

        // Operate in a block to avoid "stack too deep" error
        {
            // Cache protocol lookups for reference
            ProtocolLib.ProtocolLookups storage lookups = protocolLookups();
            // Map the offerId to the exchangeId as one-to-many
            lookups.exchangeIdsByOffer[_offerId].push(_exchangeId);

            // Orchestration commit-and-redeem flows skip the voucher NFT entirely:
            // it would be minted to the buyer and burned in the same transaction,
            // so two external calls + four storage writes that net to zero are
            // pure waste. The corresponding burn-side skip is in
            // {ExchangeRedeemBase.burnVoucher}. The skip-voucher flag is only
            // ever set on non-preminted commits, so the preminted branch below
            // always runs the increment unconditionally.
            if (_isPreminted) {
                lookups.voucherCount[buyerId]++;
            } else {
                if (_offer.quantityAvailable != type(uint256).max) {
                    // Decrement offer's quantity available
                    _offer.quantityAvailable--;
                }

                if (!_skipVoucher) {
                    // Issue voucher, unless it already exists (for preminted offers)
                    IBosonVoucher bosonVoucher = IBosonVoucher(
                        getCloneAddress(lookups, _offer.sellerId, _offer.collectionIndex)
                    );
                    uint256 tokenId = _exchangeId | (_offerId << 128);

                    // Get buyer wallet address for voucher issuance
                    address payable buyerWallet;
                    if (_offer.creator == OfferCreator.Buyer) {
                        // For buyer-created offers, get the buyer's wallet from stored buyerId
                        (, Buyer storage buyer) = fetchBuyer(buyerId);
                        buyerWallet = buyer.wallet;
                    } else {
                        // For seller-created offers, committer is the buyer
                        buyerWallet = _committer;
                    }

                    bosonVoucher.issueVoucher(tokenId, buyerWallet);
                    lookups.voucherCount[buyerId]++;
                }
            }
        }

        // Notify watchers of state change
        if (_offer.creator == OfferCreator.Buyer) {
            // Buyer-created offer: emit SellerCommitted event
            emit SellerCommitted(_offerId, _offer.sellerId, _exchangeId, exchange, voucher, _msgSender());
        } else {
            // Seller-created offer: emit BuyerCommitted event
            emit BuyerCommitted(_offerId, buyerId, _exchangeId, exchange, voucher, _msgSender());
        }

        return _exchangeId;
    }

    /**
     * @notice Authorizes a potential buyer to commit to a conditional offer.
     *
     * Emits ConditionalCommitAuthorized if successful.
     */
    function authorizeCommit(
        address _buyer,
        Condition storage _condition,
        uint256 _groupId,
        uint256 _tokenId,
        uint256 _offerId
    ) internal {
        // Cache protocol lookups for reference
        ProtocolLib.ProtocolLookups storage lookups = protocolLookups();

        GatingType gating = _condition.gating;
        mapping(uint256 => uint256) storage conditionalCommits = gating == GatingType.PerTokenId
            ? lookups.conditionalCommitsByTokenId[_tokenId]
            : lookups.conditionalCommitsByAddress[_buyer];

        // How many times has this buyer or token committed to offers in the group?
        uint256 commitCount = conditionalCommits[_groupId];
        uint256 maxCommits = _condition.maxCommits;

        if (commitCount >= maxCommits) revert MaxCommitsReached();

        bool allow = _condition.method == EvaluationMethod.Threshold
            ? holdsThreshold(_buyer, _condition, _tokenId)
            : holdsSpecificToken(_buyer, _condition, _tokenId);

        if (!allow) revert CannotCommit();

        // Increment number of commits to the group
        conditionalCommits[_groupId] = ++commitCount;

        emit ConditionalCommitAuthorized(_offerId, gating, _buyer, _tokenId, commitCount, maxCommits);
    }

    /**
     * @notice Checks if the buyer has the required balance of the conditional token.
     */
    function holdsThreshold(
        address _buyer,
        Condition storage _condition,
        uint256 _tokenId
    ) internal view returns (bool) {
        uint256 balance;

        if (_condition.tokenType == TokenType.MultiToken) {
            balance = IERC1155(_condition.tokenAddress).balanceOf(_buyer, _tokenId);
        } else if (_condition.tokenType == TokenType.NonFungibleToken) {
            balance = IERC721(_condition.tokenAddress).balanceOf(_buyer);
        } else {
            balance = IERC20(_condition.tokenAddress).balanceOf(_buyer);
        }

        return balance >= _condition.threshold;
    }

    /**
     * @notice For ERC721, checks if the buyer owns the specific token.
     */
    function holdsSpecificToken(
        address _buyer,
        Condition storage _condition,
        uint256 _tokenId
    ) internal view returns (bool) {
        return IERC721(_condition.tokenAddress).ownerOf(_tokenId) == _buyer;
    }

    /**
     * @notice Checks if the token id is inside the condition's range.
     */
    function validateConditionRange(Condition storage _condition, uint256 _tokenId) internal view {
        EvaluationMethod method = _condition.method;
        bool isMultitoken = _condition.tokenType == TokenType.MultiToken;

        if (method == EvaluationMethod.None) revert GroupHasNoCondition();

        if (method == EvaluationMethod.SpecificToken || isMultitoken) {
            // In these cases, the token id is specified by the caller must be within the range of the condition
            uint256 minTokenId = _condition.minTokenId;
            uint256 maxTokenId = _condition.maxTokenId;
            if (maxTokenId == 0) maxTokenId = minTokenId; // legacy conditions have maxTokenId == 0

            if (_tokenId < minTokenId || _tokenId > maxTokenId) revert TokenIdNotInConditionRange();
        }

        // ERC20 and ERC721 threshold does not require a token id
        if (method == EvaluationMethod.Threshold && !isMultitoken) {
            if (_tokenId != 0) revert InvalidTokenId();
        }
    }

    /**
     * @notice Handles DR fee collection from mutualizer or seller's pool.
     */
    function handleDRFeeCollection(
        uint256 _exchangeId,
        Offer storage _offer,
        DisputeResolutionTerms storage _disputeTerms,
        uint256 _drFeeAmount
    ) internal {
        address mutualizer = _disputeTerms.mutualizerAddress;
        address exchangeToken = _offer.exchangeToken;
        if (mutualizer == address(0)) {
            // Self-mutualize: take fee from seller's pool
            decreaseAvailableFunds(_offer.sellerId, _offer.exchangeToken, _drFeeAmount);
        } else {
            // Use mutualizer: request fee
            uint256 balanceBefore = getBalance(exchangeToken);

            // Request DR fee from mutualizer
            bool success = IDRFeeMutualizer(mutualizer).requestDRFee(
                _offer.sellerId,
                _drFeeAmount,
                exchangeToken,
                _exchangeId,
                _disputeTerms.disputeResolverId
            );

            uint256 balanceAfter = getBalance(exchangeToken);

            uint256 feeTransferred = balanceAfter - balanceBefore;

            if (!success || feeTransferred != _drFeeAmount) {
                revert BosonErrors.DRFeeMutualizerCannotProvideCoverage();
            }
        }

        // Emit event for DR fee request
        emit IBosonFundsBaseEvents.DRFeeRequested(
            _exchangeId,
            exchangeToken,
            _drFeeAmount,
            _disputeTerms.mutualizerAddress,
            _msgSender()
        );
    }

    /**
     * @notice Adds seller-specific offer parameters to a buyer-created offer.
     */
    function addSellerParametersToBuyerOffer(
        address _committer,
        uint256 _offerId,
        SellerOfferParams calldata _sellerParams
    ) internal returns (BosonTypes.Offer storage offer) {
        offer = getValidOffer(_offerId);
        if (offer.priceType != PriceType.Static) revert InvalidPriceType();
        if (offer.creator != OfferCreator.Buyer) revert InvalidOfferCreator();

        (bool sellerExists, uint256 sellerId) = getSellerIdByAssistant(_committer);
        if (!sellerExists) revert NotAssistant();
        offer.sellerId = sellerId;

        {
            ProtocolLib.ProtocolLookups storage lookups = protocolLookups();
            if (_sellerParams.collectionIndex > 0) {
                if (lookups.additionalCollections[sellerId].length < _sellerParams.collectionIndex) {
                    revert NoSuchCollection();
                }
                offer.collectionIndex = _sellerParams.collectionIndex;
            }

            validateRoyaltyInfo(lookups, protocolLimits(), sellerId, _sellerParams.royaltyInfo);

            offer.royaltyInfo[0] = _sellerParams.royaltyInfo;

            if (_sellerParams.mutualizerAddress != address(0)) {
                validateMutualizerInterface(_sellerParams.mutualizerAddress);

                DisputeResolutionTerms storage disputeTerms = fetchDisputeResolutionTerms(_offerId);
                disputeTerms.mutualizerAddress = _sellerParams.mutualizerAddress;
            }

            emit BuyerInitiatedOfferSetSellerParams(_offerId, sellerId, _sellerParams, _committer);
        }
    }
}

contracts/protocol/bases/ExchangeRedeemB.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import "../../domain/BosonConstants.sol";
import { IBosonExchangeEvents } from "../../interfaces/events/IBosonExchangeEvents.sol";
import { IBosonTwinEvents } from "../../interfaces/events/IBosonTwinEvents.sol";
import { IBosonVoucher } from "../../interfaces/clients/IBosonVoucher.sol";
import { DisputeBase } from "./DisputeBase.sol";
import { ProtocolLib } from "../libs/ProtocolLib.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { Address } from "@openzeppelin/contracts/utils/Address.sol";

/**
 * @title ExchangeRedeemBase
 *
 * @notice Shared logic for redeeming vouchers, burning the underlying voucher NFT,
 * and transferring bundled twins. Reused by ExchangeHandlerFacet (for the standalone
 * redeemVoucher entry point and finalizeExchange) and OrchestrationHandlerFacet2 (for
 * atomic commit-and-redeem orchestration methods).
 */
contract ExchangeRedeemBase is DisputeBase, IBosonExchangeEvents, IBosonTwinEvents {
    using Address for address;
    uint256 internal immutable EXCHANGE_ID_2_2_0; // solhint-disable-line

    /**
     * @notice Burns the voucher associated with a given exchange.
     *
     * Emits ERC721 Transfer event in call stack if successful.
     *
     * @param _exchange - the pointer to the exchange for which the voucher should be burned
     */
    function burnVoucher(Exchange storage _exchange) internal {
        // Cache protocol lookups for reference
        ProtocolLib.ProtocolLookups storage lookups = protocolLookups();

        // Decrease the voucher count
        lookups.voucherCount[_exchange.buyerId]--;

        // Burn the voucher
        uint256 offerId = _exchange.offerId;
        (, Offer storage offer) = fetchOffer(offerId);
        IBosonVoucher bosonVoucher = IBosonVoucher(getCloneAddress(lookups, offer.sellerId, offer.collectionIndex));

        uint256 tokenId = _exchange.id;
        if (tokenId >= EXCHANGE_ID_2_2_0) tokenId |= (offerId << 128);
        bosonVoucher.burnVoucher(tokenId);
    }

    /**
     * @notice Redeems a voucher (internal).
     *
     * Emits a VoucherRedeemed event if successful.
     * Emits TwinTransferred / TwinTransferFailed / TwinTransferSkipped depending on twin transfer outcome.
     *
     * Reverts if:
     * - Exchange does not exist
     * - Exchange is not in Committed state
     * - When `_skipVoucher` is false: the caller does not own the voucher
     * - Current time is prior to offer.voucherRedeemableFromDate
     * - Current time is after voucher.validUntilDate
     *
     * @param _exchangeId - the id of the exchange
     * @param _skipVoucher - when true, skip the bosonVoucher.burnVoucher() call and the
     *                       voucherCount[buyerId]-- write, AND skip the buyer-ownership
     *                       check. The flag is only set by atomic commit-and-redeem
     *                       orchestration paths, where `commitToOfferInternal` was just
     *                       called with `_committer = _msgSender()` in the same
     *                       transaction. Because the matching voucher mint was skipped,
     *                       no NFT exists for anyone to transfer, so the buyer recorded
     *                       on the exchange is provably still the caller — no need to
     *                       re-check.
     */
    function redeemVoucherInternal(uint256 _exchangeId, bool _skipVoucher) internal {
        // Get the exchange, should be in committed state
        (Exchange storage exchange, Voucher storage voucher) = getValidExchange(_exchangeId, ExchangeState.Committed);

        // Standalone redeemVoucher path: enforce that the caller owns the voucher.
        // Skipped on the orchestration commit-and-redeem path because the voucher was
        // never minted (see _skipVoucher in the natspec above), so it cannot have been
        // transferred — exchange.buyerId is guaranteed to correspond to _msgSender().
        if (!_skipVoucher) checkBuyer(exchange.buyerId);

        uint256 offerId = exchange.offerId;

        // Make sure the voucher is redeemable
        if (
            block.timestamp < fetchOfferDates(offerId).voucherRedeemableFrom || block.timestamp > voucher.validUntilDate
        ) {
            revert VoucherNotRedeemable();
        }

        // Store the time the exchange was redeemed
        voucher.redeemedDate = block.timestamp;

        // Set the exchange state to Redeemed
        exchange.state = ExchangeState.Redeemed;

        // Burn the voucher unless the matching mint was skipped on the commit side
        // (atomic commit-and-redeem orchestration).
        if (!_skipVoucher) burnVoucher(exchange);

        // Transfer any bundled twins to buyer
        transferTwins(exchange, voucher);

        // Notify watchers of state change
        emit VoucherRedeemed(offerId, _exchangeId, _msgSender());
    }

    /**
     * @notice Transfers bundled twins associated with an exchange to the buyer.
     *
     * Emits ERC20 Transfer, ERC721 Transfer, or ERC1155 TransferSingle events in call stack if successful.
     * Emits TwinTransferred if twin transfer was successful.
     * Emits TwinTransferFailed if twin transfer failed.
     * Emits TwinTransferSkipped if twin transfer was skipped when the number of twins is too high.
     *
     * If one of the twin transfers fails, the function will continue to transfer the remaining twins and
     * automatically raises a dispute for the exchange.
     *
     * @param _exchange - the exchange for which twins should be transferred
     * @param _voucher - the voucher associated with the exchange
     */
    function transferTwins(Exchange storage _exchange, Voucher storage _voucher) internal {
        uint256[] storage twinIds;
        address assistant;
        uint256 sellerId;

        // See if there is an associated bundle
        {
            (bool exists, uint256 bundleId) = fetchBundleIdByOffer(_exchange.offerId);
            if (!exists) return;

            // Get storage location for bundle
            (, Bundle storage bundle) = fetchBundle(bundleId);

            // Get the twin Ids in the bundle
            twinIds = bundle.twinIds;

            // Get seller account
            (, Seller storage seller, ) = fetchSeller(bundle.sellerId);
            sellerId = seller.id;
            assistant = seller.assistant;
        }

        bool transferFailed; // Flag to indicate if some twin transfer failed and a dispute should be raised

        // Transfer the twins
        {
            // Cache values
            address sender = _msgSender();
            uint256 twinCount = twinIds.length;

            // SINGLE_TWIN_RESERVED_GAS = 160000
            // MINIMAL_RESIDUAL_GAS = 230000
            // Next line would overflow if twinCount > (type(uint256).max - MINIMAL_RESIDUAL_GAS)/SINGLE_TWIN_RESERVED_GAS
            // Overflow happens for twinCount ~ 7.2x10^71, which is impossible to achieve
            uint256 reservedGas = (twinCount - 1) * SINGLE_TWIN_RESERVED_GAS + MINIMAL_RESIDUAL_GAS;

            // If number of twins is too high, skip the transfer and mark the transfer as failed.
            // Reserved gas is higher than the actual gas needed for successful twin redeem.
            // There is enough buffer that even if the reserved gas is above gas limit, the redeem will still succeed.
            // This check was added to prevent the DoS attack where the attacker would create a bundle with a huge number of twins.
            // For normal operations this still allows for a bundle with more than 180 twins to be redeemed, which should be enough for practical purposes.
            if (reservedGas > block.gaslimit) {
                transferFailed = true;

                emit TwinTransferSkipped(_exchange.id, twinCount, sender);
            } else {
                // Visit the twins
                for (uint256 i = 0; i < twinCount; ) {
                    // Get the twin
                    (, Twin storage twinS) = fetchTwin(twinIds[i]);

                    // Use twin struct instead of individual variables to avoid stack too deep error
                    // Don't copy the whole twin to memory immediately, only the fields that are needed
                    Twin memory twinM;
                    twinM.tokenId = twinS.tokenId;
                    twinM.amount = twinS.amount;

                    bool success;
                    {
                        twinM.tokenType = twinS.tokenType;

                        // Shouldn't decrement supply if twin supply is unlimited
                        twinM.supplyAvailable = twinS.supplyAvailable;
                        if (twinM.supplyAvailable != type(uint256).max) {
                            // Decrement by 1 if token type is NonFungible otherwise decrement amount (i.e, tokenType is MultiToken or FungibleToken)
                            twinM.supplyAvailable = twinM.tokenType == TokenType.NonFungibleToken
                                ? twinM.supplyAvailable - 1
                                : twinM.supplyAvailable - twinM.amount;

                            twinS.supplyAvailable = twinM.supplyAvailable;
                        }

                        // Transfer the token from the seller's assistant to the buyer
                        bytes memory data; // Calldata to transfer the twin

                        if (twinM.tokenType == TokenType.FungibleToken) {
                            // ERC-20 style transfer
                            data = abi.encodeCall(IERC20.transferFrom, (assistant, sender, twinM.amount));
                        } else if (twinM.tokenType == TokenType.NonFungibleToken) {
                            // Token transfer order is ascending to avoid overflow when twin supply is unlimited
                            if (twinM.supplyAvailable == type(uint256).max) {
                                twinS.tokenId++;
                            } else {
                                // Token transfer order is descending
                                twinM.tokenId += twinM.supplyAvailable;
                            }
                            // ERC-721 style transfer
                            data = abi.encodeWithSignature(
                                "safeTransferFrom(address,address,uint256,bytes)",
                                assistant,
                                sender,
                                twinM.tokenId,
                                ""
                            );
                        } else if (twinM.tokenType == TokenType.MultiToken) {
                            // ERC-1155 style transfer
                            data = abi.encodeWithSignature(
                                "safeTransferFrom(address,address,uint256,uint256,bytes)",
                                assistant,
                                sender,
                                twinM.tokenId,
                                twinM.amount,
                                ""
                            );
                        }
                        // Make call only if there is enough gas and code at address exists.
                        // If not, skip the call and mark the transfer as failed
                        twinM.tokenAddress = twinS.tokenAddress;
                        uint256 gasLeft = gasleft();
                        if (gasLeft > reservedGas && twinM.tokenAddress.isContract()) {
                            address to = twinM.tokenAddress;

                            // Handle the return value with assembly to avoid return bomb attack
                            bytes memory result;
                            assembly {
                                success := call(
                                    sub(gasLeft, reservedGas), // gasleft()-reservedGas
                                    to, // twin contract
                                    0, // ether value
                                    add(data, 0x20), // invocation calldata
                                    mload(data), // calldata length
                                    add(result, 0x20), // store return data at result
                                    0x20 // store at most 32 bytes
                                )

                                let returndataSize := returndatasize()

                                switch gt(returndataSize, 0x20)
                                case 0 {
                                    // Adjust result length in case it's shorter than 32 bytes
                                    mstore(result, returndataSize)
                                }
                                case 1 {
                                    // If return data is longer than 32 bytes, consider transfer unsuccessful
                                    success := false
                                }
                            }

                            // Check if result is empty or if result is a boolean and is true
                            success =
                                success &&
                                (result.length == 0 || (result.length == 32 && abi.decode(result, (uint256)) == 1));
                        }
                    }

                    twinM.id = twinS.id;

                    // If token transfer failed
                    if (!success) {
                        transferFailed = true;

                        emit TwinTransferFailed(
                            twinM.id,
                            twinM.tokenAddress,
                            _exchange.id,
                            twinM.tokenId,
                            twinM.amount,
                            sender
                        );
                    } else {
                        ProtocolLib.ProtocolLookups storage lookups = protocolLookups();
                        uint256 exchangeId = _exchange.id;

                        {
                            // Store twin receipt on twinReceiptsByExchange
                            TwinReceipt storage twinReceipt = lookups.twinReceiptsByExchange[exchangeId].push();
                            twinReceipt.twinId = twinM.id;
                            twinReceipt.tokenAddress = twinM.tokenAddress;
                            twinReceipt.tokenId = twinM.tokenId;
                            twinReceipt.amount = twinM.amount;
                            twinReceipt.tokenType = twinM.tokenType;
                        }
                        if (twinM.tokenType == TokenType.NonFungibleToken) {
                            updateNFTRanges(lookups, twinM, sellerId);
                        }
                        emit TwinTransferred(
                            twinM.id,
                            twinM.tokenAddress,
                            exchangeId,
                            twinM.tokenId,
                            twinM.amount,
                            sender
                        );
                    }

                    // Reduce minimum gas required for successful execution
                    reservedGas -= SINGLE_TWIN_RESERVED_GAS;

                    unchecked {
                        i++;
                    }
                }
            }
        }

        // Some twin transfer was not successful, raise dispute
        if (transferFailed) {
            raiseDisputeInternal(_exchange, _voucher, sellerId);
        }
    }

    /**
     * @notice Updates NFT ranges, so it's possible to reuse the tokens in other twins and to make
     * creation of new ranges viable.
     *
     * @param _lookups - storage pointer to the protocol lookups
     * @param _twin - storage pointer to the twin
     * @param _sellerId - the seller id
     */
    function updateNFTRanges(
        ProtocolLib.ProtocolLookups storage _lookups,
        Twin memory _twin,
        uint256 _sellerId
    ) internal {
        // Get all ranges of twins that belong to the seller and to the same token address.
        TokenRange[] storage twinRanges = _lookups.twinRangesBySeller[_sellerId][_twin.tokenAddress];
        bool unlimitedSupply = _twin.supplyAvailable == type(uint256).max;

        uint256 rangeIndex = _lookups.rangeIdByTwin[_twin.id] - 1;
        TokenRange storage range = twinRanges[rangeIndex];

        if (unlimitedSupply ? range.end == _twin.tokenId : range.start == _twin.tokenId) {
            uint256 lastIndex = twinRanges.length - 1;
            if (rangeIndex != lastIndex) {
                // Replace range with last range
                twinRanges[rangeIndex] = twinRanges[lastIndex];
                _lookups.rangeIdByTwin[range.twinId] = rangeIndex + 1;
            }

            // Remove from ranges mapping
            twinRanges.pop();

            // Delete rangeId from rangeIdByTwin mapping
            _lookups.rangeIdByTwin[_twin.id] = 0;
        } else {
            unlimitedSupply ? range.start++ : range.end--;
        }
    }
}

contracts/protocol/bases/FundsBase.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import "../../domain/BosonConstants.sol";
import { BosonErrors } from "../../domain/BosonErrors.sol";
import { BosonTypes } from "../../domain/BosonTypes.sol";
import { ProtocolLib } from "../libs/ProtocolLib.sol";
import { TokenTransferAuthorizationLib } from "../libs/TokenTransferAuthorizationLib.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IBosonFundsBaseEvents } from "../../interfaces/events/IBosonFundsEvents.sol";
import { Math } from "@openzeppelin/contracts/utils/math/Math.sol";
import { IDRFeeMutualizer } from "../../interfaces/clients/IDRFeeMutualizer.sol";
import { Context } from "@openzeppelin/contracts/utils/Context.sol";
import { IWrappedNative } from "../../interfaces/IWrappedNative.sol";

/**
 * @title FundsBase
 *
 * @dev
 */
abstract contract FundsBase is Context {
    using SafeERC20 for IERC20;
    IWrappedNative internal immutable wNative;

    /**
     * @notice Takes in the offer id and entity id and encumbers the appropriate funds during commitToOffer.
     * For seller-created offers: encumbers seller's pre-deposited deposit and validates buyer's incoming payment.
     * For buyer-created offers: encumbers buyer's pre-deposited payment and validates seller's incoming deposit.
     * If offer is preminted, caller's funds are not encumbered, but the funds are covered from pre-deposited amounts.
     *
     * Emits FundsEncumbered event if successful.
     *
     * Reverts if:
     * - Incoming payment is in native token and caller does not send enough
     * - Incoming payment is in some ERC20 token and caller also sends native currency
     * - Contract at token address does not support ERC20 function transferFrom
     * - Calling transferFrom on token fails for some reason (e.g. protocol is not approved to transfer)
     * - Entity has less pre-deposited funds available than required amount
     * - Received ERC20 token amount differs from the expected value
     *
     * @param _offerId - id of the offer with the details
     * @param _entityId - id of the committing entity (buyer for seller-created offers, seller for buyer-created offers)
     * @param _incomingAmount - the amount being paid by the committing entity
     * @param _isPreminted - flag indicating if the offer is preminted
     * @param _priceType - price type, either static or discovery
     */
    function encumberFunds(
        uint256 _offerId,
        uint256 _entityId,
        uint256 _incomingAmount,
        bool _isPreminted,
        BosonTypes.PriceType _priceType
    ) internal {
        // Load protocol entities storage
        ProtocolLib.ProtocolEntities storage pe = ProtocolLib.protocolEntities();

        // get message sender
        address sender = _msgSender();

        // fetch offer to get the exchange token, price and seller
        // this will be called only from commitToOffer so we expect that exchange actually exist
        BosonTypes.Offer storage offer = pe.offers[_offerId];
        address exchangeToken = offer.exchangeToken;

        if (!_isPreminted) {
            validateIncomingPayment(exchangeToken, _incomingAmount);
            emit IBosonFundsBaseEvents.FundsDeposited(_entityId, sender, exchangeToken, _incomingAmount);
            emit IBosonFundsBaseEvents.FundsEncumbered(_entityId, exchangeToken, _incomingAmount, sender);
        }

        if (offer.creator == BosonTypes.OfferCreator.Buyer) {
            decreaseAvailableFunds(offer.buyerId, exchangeToken, offer.price);
            emit IBosonFundsBaseEvents.FundsEncumbered(offer.buyerId, exchangeToken, offer.price, sender);
        } else {
            uint256 sellerId = offer.sellerId;
            bool isPriceDiscovery = _priceType == BosonTypes.PriceType.Discovery;
            uint256 sellerFundsEncumbered = offer.sellerDeposit +
                (_isPreminted && !isPriceDiscovery ? _incomingAmount : 0);
            decreaseAvailableFunds(sellerId, exchangeToken, sellerFundsEncumbered);
            emit IBosonFundsBaseEvents.FundsEncumbered(sellerId, exchangeToken, sellerFundsEncumbered, sender);
        }
    }

    /**
     * @notice Validates that incoming payments matches expectation. If token is a native currency, it makes sure
     * msg.value is correct. If token is ERC20, it transfers the value from the sender to the protocol.
     *
     * Emits ERC20 Transfer event in call stack if successful.
     *
     * Reverts if:
     * - Offer price is in native token and caller does not send enough
     * - Offer price is in some ERC20 token and caller also sends native currency
     * - Contract at token address does not support ERC20 function transferFrom
     * - Calling transferFrom on token fails for some reason (e.g. protocol is not approved to transfer)
     * - Received ERC20 token amount differs from the expected value
     *
     * @param _exchangeToken - address of the token (0x for native currency)
     * @param _value - value expected to receive
     */
    function validateIncomingPayment(address _exchangeToken, uint256 _value) internal {
        if (_exchangeToken == address(0)) {
            // if transfer is in the native currency, msg.value must match offer price
            if (msg.value != _value) revert BosonErrors.InsufficientValueReceived();
        } else {
            // when price is in an erc20 token, transferring the native currency is not allowed
            if (msg.value != 0) revert BosonErrors.NativeNotAllowed();

            // if transfer is in ERC20 token, try to transfer the amount from buyer to the protocol
            transferFundsIn(_exchangeToken, _value);
        }
    }

    /**
     * @notice Takes in the exchange id and releases the funds to buyer, seller and dispute resolver depending on the state of the exchange.
     * It is called only from finalizeExchange and finalizeDispute.
     *
     * Emits FundsReleased and/or ProtocolFeeCollected event if payoffs are warranted and transaction is successful.
     *
     * @param _exchangeId - exchange id
     */
    function releaseFunds(uint256 _exchangeId) internal {
        // Load protocol entities storage
        ProtocolLib.ProtocolEntities storage pe = ProtocolLib.protocolEntities();

        // Get the exchange and its state
        // Since this should be called only from certain functions from exchangeHandler and disputeHandler
        // exchange must exist and be in a completed state, so that's not checked explicitly
        BosonTypes.Exchange storage exchange = pe.exchanges[_exchangeId];

        // Get offer from storage to get the details about sellerDeposit, price, sellerId, exchangeToken and buyerCancelPenalty
        BosonTypes.Offer storage offer = pe.offers[exchange.offerId];

        // calculate the payoffs depending on state exchange is in
        BosonTypes.Payoff memory payoff;

        BosonTypes.OfferFees storage offerFee = pe.offerFees[exchange.offerId];
        uint256 offerPrice = offer.priceType == BosonTypes.PriceType.Discovery ? 0 : offer.price;
        BosonTypes.ExchangeCosts[] storage exchangeCosts = pe.exchangeCosts[_exchangeId];
        uint256 lastPrice = exchangeCosts.length == 0 ? offerPrice : exchangeCosts[exchangeCosts.length - 1].price;
        {
            // scope to avoid stack too deep errors
            BosonTypes.ExchangeState exchangeState = exchange.state;
            uint256 sellerDeposit = offer.sellerDeposit;
            bool isEscalated = pe.disputeDates[_exchangeId].escalated != 0;

            if (exchangeState == BosonTypes.ExchangeState.Completed) {
                // COMPLETED
                payoff.protocol = offerFee.protocolFee;
                // buyerPayoff is 0
                payoff.agent = offerFee.agentFee;
                payoff.seller = offerPrice + sellerDeposit - payoff.protocol - payoff.agent;
            } else if (exchangeState == BosonTypes.ExchangeState.Revoked) {
                // REVOKED
                // sellerPayoff is 0
                payoff.buyer = lastPrice + sellerDeposit;
            } else if (exchangeState == BosonTypes.ExchangeState.Canceled) {
                // CANCELED
                uint256 buyerCancelPenalty = offer.buyerCancelPenalty;
                payoff.seller = sellerDeposit + buyerCancelPenalty;
                payoff.buyer = lastPrice - buyerCancelPenalty;
            } else if (exchangeState == BosonTypes.ExchangeState.Disputed) {
                // DISPUTED
                // determine if buyerEscalationDeposit was encumbered or not
                // if dispute was escalated, disputeDates.escalated is populated
                uint256 buyerEscalationDeposit = isEscalated
                    ? pe.disputeResolutionTerms[exchange.offerId].buyerEscalationDeposit
                    : 0;

                // get the information about the dispute, which must exist
                BosonTypes.Dispute storage dispute = pe.disputes[_exchangeId];
                BosonTypes.DisputeState disputeState = dispute.state;

                if (disputeState == BosonTypes.DisputeState.Retracted) {
                    // RETRACTED - same as "COMPLETED"
                    payoff.protocol = offerFee.protocolFee;
                    payoff.agent = offerFee.agentFee;
                    // buyerPayoff is 0
                    payoff.seller =
                        offerPrice +
                        sellerDeposit -
                        payoff.protocol -
                        payoff.agent +
                        buyerEscalationDeposit;

                    // DR is paid if dispute was escalated
                    payoff.disputeResolver = isEscalated ? pe.disputeResolutionTerms[exchange.offerId].feeAmount : 0;
                } else if (disputeState == BosonTypes.DisputeState.Refused) {
                    // REFUSED
                    payoff.seller = sellerDeposit;
                    payoff.buyer = lastPrice + buyerEscalationDeposit;
                    // DR is not paid when dispute is refused
                } else {
                    // RESOLVED or DECIDED
                    uint256 commonPot = sellerDeposit + buyerEscalationDeposit;
                    payoff.buyer = applyPercent(commonPot, dispute.buyerPercent);
                    payoff.seller = commonPot - payoff.buyer;

                    payoff.buyer = payoff.buyer + applyPercent(lastPrice, dispute.buyerPercent);
                    payoff.seller = payoff.seller + offerPrice - applyPercent(offerPrice, dispute.buyerPercent);

                    // DR is always paid for escalated disputes (Decided or Resolved with escalation)
                    if (isEscalated) {
                        payoff.disputeResolver = pe.disputeResolutionTerms[exchange.offerId].feeAmount;
                    }
                }
            }
        }

        address exchangeToken = offer.exchangeToken;

        // Original seller and last buyer are done
        // Release funds to intermediate sellers (if they exist)
        // and add the protocol fee to the total
        {
            (uint256 sequentialProtocolFee, uint256 sequentialRoyalties) = releaseFundsToIntermediateSellers(
                _exchangeId,
                exchange.state,
                offerPrice,
                exchangeToken,
                offer
            );
            payoff.seller += sequentialRoyalties;
            payoff.protocol += sequentialProtocolFee;
        }

        // Store payoffs to availablefunds and notify the external observers
        address sender = _msgSender();
        if (payoff.seller > 0) {
            increaseAvailableFundsAndEmitEvent(_exchangeId, offer.sellerId, exchangeToken, payoff.seller, sender);
        }
        if (payoff.buyer > 0) {
            increaseAvailableFundsAndEmitEvent(_exchangeId, exchange.buyerId, exchangeToken, payoff.buyer, sender);
        }

        if (payoff.protocol > 0) {
            increaseAvailableFunds(PROTOCOL_ENTITY_ID, exchangeToken, payoff.protocol);
            emit IBosonFundsBaseEvents.ProtocolFeeCollected(_exchangeId, exchangeToken, payoff.protocol, sender);
        }
        if (payoff.agent > 0) {
            // Get the agent for offer
            uint256 agentId = ProtocolLib.protocolLookups().agentIdByOffer[exchange.offerId];
            increaseAvailableFundsAndEmitEvent(_exchangeId, agentId, exchangeToken, payoff.agent, sender);
        }
        BosonTypes.DisputeResolutionTerms memory drTerms = pe.disputeResolutionTerms[offer.id];
        if (payoff.disputeResolver > 0) {
            increaseAvailableFundsAndEmitEvent(
                _exchangeId,
                drTerms.disputeResolverId,
                exchangeToken,
                payoff.disputeResolver,
                sender
            );
        }

        // Return unused DR fee to mutualizer or seller's pool
        if (drTerms.feeAmount != 0) {
            payoff.mutualizer = drTerms.feeAmount - payoff.disputeResolver;

            // Use exchange-level mutualizer address (locked at commitment time)
            address mutualizerAddress = exchange.mutualizerAddress;
            if (mutualizerAddress == address(0)) {
                if (payoff.mutualizer > 0) {
                    increaseAvailableFundsAndEmitEvent(
                        _exchangeId,
                        offer.sellerId,
                        exchangeToken,
                        payoff.mutualizer,
                        sender
                    );
                }
            } else {
                if (payoff.mutualizer > 0) {
                    if (exchangeToken == address(0)) {
                        exchangeToken = address(wNative);
                        wNative.deposit{ value: payoff.mutualizer }();
                    }
                    uint256 oldAllowance = IERC20(exchangeToken).allowance(address(this), mutualizerAddress);
                    IERC20(exchangeToken).forceApprove(mutualizerAddress, payoff.mutualizer + oldAllowance);
                }

                try
                    IDRFeeMutualizer(mutualizerAddress).finalizeExchange{
                        gas: ProtocolLib.protocolLimits().mutualizerGasStipend
                    }(_exchangeId, payoff.mutualizer)
                {
                    emit IBosonFundsBaseEvents.DRFeeReturned(
                        _exchangeId,
                        exchangeToken,
                        payoff.mutualizer,
                        mutualizerAddress,
                        sender
                    );
                } catch {
                    // Ignore failure to not block the main flow
                    emit IBosonFundsBaseEvents.DRFeeReturnFailed(
                        _exchangeId,
                        exchangeToken,
                        payoff.mutualizer,
                        mutualizerAddress,
                        sender
                    );
                }
            }
        }
    }

    /**
     * @notice Takes the exchange id and releases the funds to original seller if offer.priceType is Discovery
     * and to all intermediate resellers in case of sequential commit, depending on the state of the exchange.
     * It is called only from releaseFunds. Protocol fee and royalties are calculated and returned to releaseFunds, where they are added to the total.
     *
     * Emits FundsReleased events for non zero payoffs.
     *
     * @param _exchangeId - exchange id
     * @param _exchangeState - state of the exchange
     * @param _initialPrice - initial price of the offer
     * @param _exchangeToken - address of the token used for the exchange
     * @param _offer - offer struct
     * @return protocolFee - protocol fee from secondary sales
     * @return sellerRoyalties - royalties from secondary sales collected for the seller
     */
    function releaseFundsToIntermediateSellers(
        uint256 _exchangeId,
        BosonTypes.ExchangeState _exchangeState,
        uint256 _initialPrice,
        address _exchangeToken,
        BosonTypes.Offer storage _offer
    ) internal returns (uint256 protocolFee, uint256 sellerRoyalties) {
        BosonTypes.ExchangeCosts[] storage exchangeCosts;

        // calculate effective price multiplier
        uint256 effectivePriceMultiplier;
        {
            ProtocolLib.ProtocolEntities storage pe = ProtocolLib.protocolEntities();

            exchangeCosts = pe.exchangeCosts[_exchangeId];

            // if price type was static and no sequential commit happened, just return
            if (exchangeCosts.length == 0) {
                return (0, 0);
            }

            {
                if (_exchangeState == BosonTypes.ExchangeState.Completed) {
                    // COMPLETED, buyer pays full price
                    effectivePriceMultiplier = HUNDRED_PERCENT;
                } else if (
                    _exchangeState == BosonTypes.ExchangeState.Revoked ||
                    _exchangeState == BosonTypes.ExchangeState.Canceled
                ) {
                    // REVOKED or CANCELED, buyer pays nothing (buyerCancelPenalty is not considered payment)
                    effectivePriceMultiplier = 0;
                } else if (_exchangeState == BosonTypes.ExchangeState.Disputed) {
                    // DISPUTED
                    // get the information about the dispute, which must exist
                    BosonTypes.Dispute storage dispute = pe.disputes[_exchangeId];
                    BosonTypes.DisputeState disputeState = dispute.state;

                    if (disputeState == BosonTypes.DisputeState.Retracted) {
                        // RETRACTED - same as "COMPLETED"
                        effectivePriceMultiplier = HUNDRED_PERCENT;
                    } else if (disputeState == BosonTypes.DisputeState.Refused) {
                        // REFUSED, buyer pays nothing
                        effectivePriceMultiplier = 0;
                    } else {
                        // RESOLVED or DECIDED
                        effectivePriceMultiplier = HUNDRED_PERCENT - dispute.buyerPercent;
                    }
                }
            }
        }

        uint256 resellerBuyPrice = _initialPrice; // the price that reseller paid for the voucher
        address msgSender = _msgSender();
        uint256 len = exchangeCosts.length;
        for (uint256 i = 0; i < len; ) {
            // Since all elements of exchangeCosts[i] are used, it makes sense to copy them to memory
            BosonTypes.ExchangeCosts memory secondaryCommit = exchangeCosts[i];

            // amount to be released
            uint256 currentResellerAmount;

            // inside the scope to avoid stack too deep error
            {
                if (effectivePriceMultiplier > 0) {
                    protocolFee =
                        protocolFee +
                        applyPercent(secondaryCommit.protocolFeeAmount, effectivePriceMultiplier);
                    sellerRoyalties += distributeRoyalties(
                        _exchangeId,
                        _offer,
                        secondaryCommit,
                        effectivePriceMultiplier
                    );
                }

                // secondary price without protocol fee and royalties
                uint256 reducedSecondaryPrice = secondaryCommit.price -
                    secondaryCommit.protocolFeeAmount -
                    secondaryCommit.royaltyAmount;

                // Calculate amount to be released to the reseller:
                // + part of the price that they paid (relevant for unhappy paths)
                // + price of the voucher that they sold reduced for part that goes to next reseller, royalties and protocol fee
                // - immediate payout that was released already during the sequential commit
                currentResellerAmount =
                    applyPercent(resellerBuyPrice, (HUNDRED_PERCENT - effectivePriceMultiplier)) +
                    secondaryCommit.price -
                    applyPercent(secondaryCommit.price, (HUNDRED_PERCENT - effectivePriceMultiplier)) -
                    applyPercent(secondaryCommit.protocolFeeAmount, effectivePriceMultiplier) -
                    applyPercent(secondaryCommit.royaltyAmount, effectivePriceMultiplier) -
                    Math.min(resellerBuyPrice, reducedSecondaryPrice);

                resellerBuyPrice = secondaryCommit.price;
            }

            if (currentResellerAmount > 0) {
                increaseAvailableFundsAndEmitEvent(
                    _exchangeId,
                    secondaryCommit.resellerId,
                    _exchangeToken,
                    currentResellerAmount,
                    msgSender
                );
            }

            unchecked {
                i++;
            }
        }
    }

    /**
     * @notice Forwards values to increaseAvailableFunds and emits notifies external listeners.
     *
     * Emits FundsReleased events
     *
     * @param _exchangeId - exchange id
     * @param _entityId - id of the entity to which the funds are released
     * @param _tokenAddress - address of the token used for the exchange
     * @param _amount - amount of tokens to be released
     * @param _sender - address of the sender that executed the transaction
     */
    function increaseAvailableFundsAndEmitEvent(
        uint256 _exchangeId,
        uint256 _entityId,
        address _tokenAddress,
        uint256 _amount,
        address _sender
    ) internal {
        increaseAvailableFunds(_entityId, _tokenAddress, _amount);
        emit IBosonFundsBaseEvents.FundsReleased(_exchangeId, _entityId, _tokenAddress, _amount, _sender);
    }

    /**
     * @notice Tries to transfer tokens from the caller to the protocol.
     *
     * Emits ERC20 Transfer event in call stack if successful.
     *
     * Reverts if:
     * - Contract at token address does not support ERC20 function transferFrom
     * - Calling transferFrom on token fails for some reason (e.g. protocol is not approved to transfer)
     * - Received ERC20 token amount differs from the expected value
     *
     * @param _tokenAddress - address of the token to be transferred
     * @param _from - address to transfer funds from
     * @param _amount - amount to be transferred
     */
    function transferFundsIn(address _tokenAddress, address _from, uint256 _amount) internal {
        if (_amount > 0) {
            // protocol balance before the transfer
            uint256 protocolTokenBalanceBefore = IERC20(_tokenAddress).balanceOf(address(this));

            // If a metatx parked a queue, the library may consume the next entry
            // using a supported authorization strategy (e.g. ERC-3009,
            // EIP-2612, or Permit2) to pull funds into the protocol. If no
            // queued authorization is available, it is exhausted, or a fallback
            // marker is encountered, we use the standard allowance path instead.
            // Note: only the ERC-3009 receiveWithAuthorization path enforces
            // `to == msg.sender` on the token side; do not assume equivalent
            // recipient checks for other authorization strategies.
            if (!TokenTransferAuthorizationLib.consumeForTransfer(_tokenAddress, _from, address(this), _amount)) {
                IERC20(_tokenAddress).safeTransferFrom(_from, address(this), _amount);
            }

            // protocol balance after the transfer
            uint256 protocolTokenBalanceAfter = IERC20(_tokenAddress).balanceOf(address(this));
            // make sure that expected amount of tokens was transferred
            if (protocolTokenBalanceAfter - protocolTokenBalanceBefore != _amount)
                revert BosonErrors.InsufficientValueReceived();
        } else {
            // Zero-amount pull: no transfer happens, but still advance the queue
            // head so the off-chain caller can supply a queue whose layout is
            // independent of runtime amounts. No-op if no queue is loaded.
            TokenTransferAuthorizationLib.discardNext();
        }
    }

    /**
     * @notice Same as transferFundsIn(address _tokenAddress, address _from, uint256 _amount),
     * but _from is message sender
     *
     * @param _tokenAddress - address of the token to be transferred
     * @param _amount - amount to be transferred
     */
    function transferFundsIn(address _tokenAddress, uint256 _amount) internal {
        transferFundsIn(_tokenAddress, _msgSender(), _amount);
    }

    /**
     * @notice Tries to transfer native currency or tokens from the protocol to the recipient.
     *
     * Emits FundsWithdrawn event if successful.
     * Emits ERC20 Transfer event in call stack if ERC20 token is withdrawn and transfer is successful.
     *
     * Reverts if:
     * - Transfer of native currency is not successful (i.e. recipient is a contract which reverted)
     * - Contract at token address does not support ERC20 function transfer
     * - Available funds is less than amount to be decreased
     *
     * @param _entityId - id of entity for which funds should be decreased, or 0 for protocol
     * @param _tokenAddress - address of the token to be transferred
     * @param _to - address of the recipient
     * @param _amount - amount to be transferred
     */
    function transferFundsOut(uint256 _entityId, address _tokenAddress, address payable _to, uint256 _amount) internal {
        // first decrease the amount to prevent the reentrancy attack
        decreaseAvailableFunds(_entityId, _tokenAddress, _amount);

        // try to transfer the funds
        transferFundsOut(_tokenAddress, _to, _amount);

        // notify the external observers
        emit IBosonFundsBaseEvents.FundsWithdrawn(_entityId, _to, _tokenAddress, _amount, _msgSender());
    }

    /**
     * @notice Tries to transfer native currency or tokens from the protocol to the recipient.
     *
     * Emits ERC20 Transfer event in call stack if ERC20 token is withdrawn and transfer is successful.
     *
     * Reverts if:
     * - Transfer of native currency is not successful (i.e. recipient is a contract which reverted)
     * - Contract at token address does not support ERC20 function transfer
     * - Available funds is less than amount to be decreased
     *
     * @param _tokenAddress - address of the token to be transferred
     * @param _to - address of the recipient
     * @param _amount - amount to be transferred
     */
    function transferFundsOut(address _tokenAddress, address payable _to, uint256 _amount) internal {
        // try to transfer the funds
        if (_tokenAddress == address(0)) {
            // transfer native currency
            (bool success, ) = _to.call{ value: _amount }("");
            if (!success) revert BosonErrors.TokenTransferFailed();
        } else {
            // transfer ERC20 tokens
            IERC20(_tokenAddress).safeTransfer(_to, _amount);
        }
    }

    /**
     * @notice Increases the amount, available to withdraw or use as a seller deposit.
     *
     * @param _entityId - id of entity for which funds should be increased, or 0 for protocol
     * @param _tokenAddress - funds contract address or zero address for native currency
     * @param _amount - amount to be credited
     */
    function increaseAvailableFunds(uint256 _entityId, address _tokenAddress, uint256 _amount) internal {
        ProtocolLib.ProtocolLookups storage pl = ProtocolLib.protocolLookups();

        // if the current amount of token is 0, the token address must be added to the token list
        mapping(address => uint256) storage availableFunds = pl.availableFunds[_entityId];
        if (availableFunds[_tokenAddress] == 0) {
            address[] storage tokenList = pl.tokenList[_entityId];
            tokenList.push(_tokenAddress);
            //Set index mapping. Should be index in tokenList array + 1
            pl.tokenIndexByAccount[_entityId][_tokenAddress] = tokenList.length;
        }

        // update the available funds
        availableFunds[_tokenAddress] += _amount;
    }

    /**
     * @notice Decreases the amount available to withdraw or use as a seller deposit.
     *
     * Reverts if:
     * - Available funds is less than amount to be decreased
     *
     * @param _entityId - id of entity for which funds should be decreased, or 0 for protocol
     * @param _tokenAddress - funds contract address or zero address for native currency
     * @param _amount - amount to be taken away
     */
    function decreaseAvailableFunds(uint256 _entityId, address _tokenAddress, uint256 _amount) internal {
        if (_amount > 0) {
            ProtocolLib.ProtocolLookups storage pl = ProtocolLib.protocolLookups();

            // get available funds from storage
            mapping(address => uint256) storage availableFunds = pl.availableFunds[_entityId];
            uint256 entityFunds = availableFunds[_tokenAddress];

            // make sure that seller has enough funds in the pool and reduce the available funds
            if (entityFunds < _amount) revert BosonErrors.InsufficientAvailableFunds();

            // Use unchecked to optimize execution cost. The math is safe because of the require above.
            unchecked {
                availableFunds[_tokenAddress] = entityFunds - _amount;
            }

            // if available funds are totally emptied, the token address is removed from the seller's tokenList
            if (entityFunds == _amount) {
                // Get the index in the tokenList array, which is 1 less than the tokenIndexByAccount index
                address[] storage tokenList = pl.tokenList[_entityId];
                uint256 lastTokenIndex = tokenList.length - 1;
                mapping(address => uint256) storage entityTokens = pl.tokenIndexByAccount[_entityId];
                uint256 index = entityTokens[_tokenAddress] - 1;

                // if target is last index then only pop and delete are needed
                // otherwise, we overwrite the target with the last token first
                if (index != lastTokenIndex) {
                    // Need to fill gap caused by delete if more than one element in storage array
                    address tokenToMove = tokenList[lastTokenIndex];
                    // Copy the last token in the array to this index to fill the gap
                    tokenList[index] = tokenToMove;
                    // Reset index mapping. Should be index in tokenList array + 1
                    entityTokens[tokenToMove] = index + 1;
                }
                // Delete last token address in the array, which was just moved to fill the gap
                tokenList.pop();
                // Delete from index mapping
                delete entityTokens[_tokenAddress];
            }
        }
    }

    /**
     * @notice Distributes the royalties to external recipients and seller's treasury.
     *
     * @param _offer - storage pointer to the offer
     * @param _secondaryCommit - information about the secondary commit (royaltyInfoIndex, price, escrowedRoyaltyAmount)
     * @param _effectivePriceMultiplier - multiplier for the price, depending on the state of the exchange
     */
    function distributeRoyalties(
        uint256 _exchangeId,
        BosonTypes.Offer storage _offer,
        BosonTypes.ExchangeCosts memory _secondaryCommit,
        uint256 _effectivePriceMultiplier
    ) internal returns (uint256 sellerRoyalties) {
        address sender = _msgSender();
        address exchangeToken = _offer.exchangeToken;
        BosonTypes.RoyaltyInfo storage _royaltyInfo = _offer.royaltyInfo[_secondaryCommit.royaltyInfoIndex];
        uint256 len = _royaltyInfo.recipients.length;
        uint256 totalAmount;
        uint256 effectivePrice = applyPercent(_secondaryCommit.price, _effectivePriceMultiplier);
        ProtocolLib.ProtocolLookups storage pl = ProtocolLib.protocolLookups();
        for (uint256 i = 0; i < len; ) {
            address payable recipient = _royaltyInfo.recipients[i];
            uint256 amount = applyPercent(_royaltyInfo.bps[i], effectivePrice);
            totalAmount += amount;
            if (recipient == address(0)) {
                // goes to seller's treasury
                sellerRoyalties += amount;
            } else {
                // Make funds available to withdraw
                if (amount > 0) {
                    increaseAvailableFundsAndEmitEvent(
                        _exchangeId,
                        pl.royaltyRecipientIdByWallet[recipient],
                        exchangeToken,
                        amount,
                        sender
                    );
                }
            }

            unchecked {
                i++;
            }
        }

        // if there is a remainder due to rounding, it goes to the seller's treasury
        sellerRoyalties =
            sellerRoyalties +
            applyPercent(_secondaryCommit.royaltyAmount, _effectivePriceMultiplier) -
            totalAmount;
    }

    /**
     * @notice Returns the balance of the protocol for the given token address
     *
     * @param _tokenAddress - the address of the token to check the balance for
     * @return balance - the balance of the protocol for the given token address
     */
    function getBalance(address _tokenAddress) internal view returns (uint256) {
        return _tokenAddress == address(0) ? address(this).balance : IERC20(_tokenAddress).balanceOf(address(this));
    }

    /**
     * @notice Calulates the percentage of the amount.
     *
     * @param _amount - amount to be used for the calculation
     * @param _percent - percentage to be calculated, in basis points (1% = 100, 100% = 10000)
     */
    function applyPercent(uint256 _amount, uint256 _percent) internal pure returns (uint256) {
        if (_percent == HUNDRED_PERCENT) return _amount;
        if (_percent == 0) return 0;

        return (_amount * _percent) / HUNDRED_PERCENT;
    }
}

contracts/protocol/bases/GroupBase.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import "./../../domain/BosonConstants.sol";
import { IBosonGroupEvents } from "../../interfaces/events/IBosonGroupEvents.sol";
import { ProtocolBase } from "./../bases/ProtocolBase.sol";
import { ProtocolLib } from "./../libs/ProtocolLib.sol";

/**
 * @title GroupBase
 *
 * @notice Provides methods for group creation that can be shared across facets
 */
contract GroupBase is ProtocolBase, IBosonGroupEvents {
    /**
     * @notice Creates a group.
     *
     * Emits a GroupCreated event if successful.
     *
     * Reverts if:
     * - Caller is not an assistant
     * - Any of offers belongs to different seller
     * - Any of offers does not exist
     * - Offer exists in a different group
     * - Condition fields are invalid
     *
     * @param _group - the fully populated struct with group id set to 0x0
     * @param _condition - the fully populated condition struct
     * @param _authenticate - whether to authenticate the caller. Use false when called from a handler that already authenticated the caller. _group.sellerId must be set in this case.
     */
    function createGroupInternal(Group memory _group, Condition calldata _condition, bool _authenticate) internal {
        // Cache protocol lookups for reference
        ProtocolLib.ProtocolLookups storage lookups = protocolLookups();

        // get message sender
        address sender = _msgSender();

        // authenticate caller if needed
        if (_authenticate) {
            (bool exists, uint256 sellerId) = getSellerIdByAssistant(sender);
            if (!exists || _group.sellerId != sellerId) revert NotAssistant();
        }

        // condition must be valid
        if (!validateCondition(_condition)) revert InvalidConditionParameters();

        // Get the next group and increment the counter
        uint256 groupId = protocolCounters().nextGroupId++;

        for (uint256 i; i < _group.offerIds.length; ++i) {
            // make sure offer exists and belongs to the seller
            if (_authenticate) getValidOfferWithSellerCheck(_group.offerIds[i]);

            // Offer should not belong to another group already
            (bool exist, ) = getGroupIdByOffer(_group.offerIds[i]);
            if (exist) revert OfferMustBeUnique();

            // add to groupIdByOffer mapping
            lookups.groupIdByOffer[_group.offerIds[i]] = groupId;

            // Set index mapping. Should be index in offerIds + 1
            lookups.offerIdIndexByGroup[groupId][_group.offerIds[i]] = i + 1;
        }

        // Get storage location for group
        (, Group storage group) = fetchGroup(groupId);

        // Set group props individually since memory structs can't be copied to storage
        group.id = _group.id = groupId;
        group.sellerId = _group.sellerId;
        group.offerIds = _group.offerIds;

        // Store the condition
        storeCondition(groupId, _condition);

        // Notify watchers of state change
        emit GroupCreated(groupId, _group.sellerId, _group, _condition, sender);
    }

    /**
     * @notice Store a condition struct associated with a given group id.
     *
     * @param _groupId - the group id
     * @param _condition - the condition
     */
    function storeCondition(uint256 _groupId, Condition calldata _condition) internal {
        // Get storage locations for condition
        Condition storage condition = fetchCondition(_groupId);

        // Set condition props individually since calldata structs can't be copied to storage
        condition.method = _condition.method;
        condition.tokenType = _condition.tokenType;
        condition.tokenAddress = _condition.tokenAddress;
        condition.gating = _condition.gating;
        condition.minTokenId = _condition.minTokenId;
        condition.threshold = _condition.threshold;
        condition.maxCommits = _condition.maxCommits;
        condition.maxTokenId = _condition.maxTokenId;
    }

    /**
     * @notice Validates that condition parameters make sense.
     *
     * An invalid condition is one that fits any of the following criteria:
     * - EvaluationMethod.None: any field different from zero
     * - EvaluationMethod.Threshold:
     *    - Token address, maxCommits, or threshold is zero.
     *    - Min token id is greater than max token id.
     *    - TokenType is FungibleToken or NonFungibleToken and
     *       - Min token id is not 0
     *       - Gating is not PerAddress
     * - EvaluationMethod.SpecificToken:
     *    - TokenType is FungibleToken or MultiToken
     *    - Token address, maxCommits is zero.
     *    - Threshold is not zero.
     *    - Min token id is greater than max token id.
     *
     * @param _condition - fully populated condition struct
     * @return valid - validity of condition
     *
     */
    function validateCondition(Condition calldata _condition) internal pure returns (bool) {
        if (_condition.method == EvaluationMethod.None) {
            // bitwise OR of all fields should be zero
            return
                (uint8(_condition.tokenType) |
                    uint160(_condition.tokenAddress) |
                    uint8(_condition.gating) |
                    _condition.minTokenId |
                    _condition.threshold |
                    _condition.maxCommits |
                    _condition.maxTokenId) == 0;
        }

        // SpecificToken or Threshold
        if (
            _condition.maxCommits == 0 ||
            _condition.tokenAddress == address(0) ||
            _condition.minTokenId > _condition.maxTokenId
        ) return false;

        if (_condition.method == EvaluationMethod.Threshold) {
            if (_condition.threshold == 0) return false;

            // Fungible token and NonFungible token cannot have token id range or per token id gating
            if (
                _condition.tokenType != TokenType.MultiToken &&
                (_condition.minTokenId != 0 || _condition.gating != GatingType.PerAddress)
            ) return false;
        } else {
            // SpecificToken
            // Only NonFungible is allowed
            return (_condition.tokenType == TokenType.NonFungibleToken && _condition.threshold == 0);
        }

        return true;
    }

    /**
     * @notice Adds offers to an existing group.
     *
     * Emits a GroupUpdated event if successful.
     *
     * Reverts if:
     * - Caller is not the seller
     * - Offer ids param is an empty list
     * - Group does not exist
     * - Any of offers belongs to different seller
     * - Any of offers does not exist
     * - Offer exists in a different group
     * - Offer ids param contains duplicated offers
     *
     * @param _groupId  - the id of the group to be updated
     * @param _offerIds - array of offer ids to be added to the group
     */
    function addOffersToGroupInternal(uint256 _groupId, uint256[] memory _offerIds) internal {
        // Cache protocol lookups for reference
        ProtocolLib.ProtocolLookups storage lookups = protocolLookups();

        // check if group can be updated
        (uint256 sellerId, Group storage group) = preUpdateChecks(_groupId, _offerIds);

        for (uint256 i = 0; i < _offerIds.length; ) {
            uint256 offerId = _offerIds[i];

            getValidOfferWithSellerCheck(offerId);

            // Offer should not belong to another group already
            (bool exist, ) = getGroupIdByOffer(offerId);
            if (exist) revert OfferMustBeUnique();

            // add to groupIdByOffer mapping
            lookups.groupIdByOffer[offerId] = _groupId;

            // add to group struct
            group.offerIds.push(offerId);

            // Set index mapping. Should be index in offerIds + 1
            lookups.offerIdIndexByGroup[_groupId][offerId] = group.offerIds.length;

            unchecked {
                i++;
            }
        }

        // Get the condition
        Condition storage condition = fetchCondition(_groupId);

        // Notify watchers of state change
        emit GroupUpdated(_groupId, sellerId, group, condition, _msgSender());
    }

    /**
     * @notice Checks that update can be done before performing an update
     * and returns seller id and group storage pointer for further use.
     *
     * Reverts if:
     * - Caller is not the seller
     * - Offer ids param is an empty list
     * - Group does not exist
     *
     * @param _groupId  - the id of the group to be updated
     * @param _offerIds - array of offer ids to be added to or removed from the group
     * @return sellerId  - the seller id
     * @return group - the group details
     */
    function preUpdateChecks(
        uint256 _groupId,
        uint256[] memory _offerIds
    ) internal view returns (uint256 sellerId, Group storage group) {
        // make sure that at least something will be updated
        if (_offerIds.length == 0) revert NothingUpdated();

        // Get storage location for group
        bool exists;
        (exists, group) = fetchGroup(_groupId);

        if (!exists) revert NoSuchGroup();

        // Get seller id, we assume seller id exists if group exists
        (, sellerId) = getSellerIdByAssistant(_msgSender());

        // Caller's seller id must match group seller id
        if (sellerId != group.sellerId) revert NotAssistant();
    }
}

contracts/protocol/bases/OfferBase.sol.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import { IBosonOfferEvents } from "../../interfaces/events/IBosonOfferEvents.sol";
import { ProtocolBase } from "./../bases/ProtocolBase.sol";
import { BuyerBase } from "./../bases/BuyerBase.sol";
import { ProtocolLib } from "./../libs/ProtocolLib.sol";
import { IBosonVoucher } from "../../interfaces/clients/IBosonVoucher.sol";
import { IERC165 } from "../../interfaces/IERC165.sol";
import { IDRFeeMutualizer } from "../../interfaces/clients/IDRFeeMutualizer.sol";
import "./../../domain/BosonConstants.sol";

/**
 * @title OfferBase
 *
 * @dev Provides methods for offer creation that can be shared across facets.
 */
contract OfferBase is ProtocolBase, BuyerBase, IBosonOfferEvents {
    string private constant OFFER_TYPE =
        "Offer(uint256 sellerId,uint256 price,uint256 sellerDeposit,uint256 buyerCancelPenalty,uint256 quantityAvailable,address exchangeToken,string metadataUri,string metadataHash,uint256 collectionIndex,RoyaltyInfo royaltyInfo,uint8 creator,uint256 buyerId)";
    string private constant ROYALTY_INFO_TYPE = "RoyaltyInfo(address[] recipients,uint256[] bps)";
    string private constant OFFER_DATES_TYPE =
        "OfferDates(uint256 validFrom,uint256 validUntil,uint256 voucherRedeemableFrom,uint256 voucherRedeemableUntil)";
    string private constant OFFER_DURATIONS_TYPE =
        "OfferDurations(uint256 disputePeriod,uint256 voucherValid,uint256 resolutionPeriod)";
    string private constant DR_PARAMETERS_TYPE = "DRParameters(uint256 disputeResolverId,address mutualizerAddress)";
    string private constant CONDITION_TYPE =
        "Condition(uint8 method,uint8 tokenType,address tokenAddress,uint8 gating,uint256 minTokenId,uint256 threshold,uint256 maxCommits,uint256 maxTokenId)";
    string private constant FULL_OFFER_TYPE =
        "FullOffer(Offer offer,OfferDates offerDates,OfferDurations offerDurations,DRParameters drParameters,Condition condition,uint256 agentId,uint256 feeLimit,bool useDepositedFunds)";

    bytes32 private immutable OFFER_TYPEHASH = keccak256(abi.encodePacked(OFFER_TYPE, ROYALTY_INFO_TYPE));
    bytes32 private immutable ROYALTY_INFO_TYPEHASH = keccak256(bytes(ROYALTY_INFO_TYPE));
    bytes32 private immutable OFFER_DATES_TYPEHASH = keccak256(bytes(OFFER_DATES_TYPE));
    bytes32 private immutable OFFER_DURATIONS_TYPEHASH = keccak256(bytes(OFFER_DURATIONS_TYPE));
    bytes32 private immutable DR_PARAMETERS_TYPEHASH = keccak256(bytes(DR_PARAMETERS_TYPE));
    bytes32 private immutable CONDITION_TYPEHASH = keccak256(bytes(CONDITION_TYPE));
    bytes32 private immutable FULL_OFFER_TYPEHASH =
        keccak256(
            abi.encodePacked(
                abi.encodePacked(FULL_OFFER_TYPE, CONDITION_TYPE), // nested abi.encodePacked due to stack-too-deep error
                DR_PARAMETERS_TYPE,
                OFFER_TYPE,
                OFFER_DATES_TYPE,
                OFFER_DURATIONS_TYPE,
                ROYALTY_INFO_TYPE
            )
        );

    /**
     * @notice Creates offer. Can be reused among different facets.
     *
     * Emits an OfferCreated event if successful.
     *
     * Reverts if:
     * - Caller is not an assistant in case of seller-initiated offer
     * - sellerId is not 0 when buyer-initiated offer is created
     * - collectionIndex is not 0 when buyer-initiated offer is created
     * - royaltyInfo is not empty when buyer-initiated offer is created
     * - mutualizerAddress is not zero when buyer-initiated offer is created
     * - quantityAvailable is not 1 when buyer-initiated offer is created
     * - priceType is not Static when buyer-initiated offer is created
     * - Invalid offer creator value specified (OfferCreator.Seller or OfferCreator.Buyer)
     * - Valid from date is greater than valid until date
     * - Valid until date is not in the future
     * - Both voucher expiration date and voucher expiration period are defined
     * - Neither of voucher expiration date and voucher expiration period are defined
     * - Voucher redeemable period is fixed, but it ends before it starts
     * - Voucher redeemable period is fixed, but it ends before offer expires
     * - Dispute period is less than minimum dispute period
     * - Resolution period is not between the minimum and the maximum resolution period
     * - Voided is set to true
     * - Available quantity is set to zero
     * - Dispute resolver wallet is not registered, except for absolute zero offers with unspecified dispute resolver
     * - Dispute resolver is not active, except for absolute zero offers with unspecified dispute resolver
     * - Seller is not on dispute resolver's seller allow list
     * - Dispute resolver does not accept fees in the exchange token
     * - Buyer cancel penalty is greater than price
     * - When agent id is non zero:
     *   - If Agent does not exist
     * - If the sum of agent fee amount and protocol fee amount is greater than the offer fee limit determined by the protocol
     * - If the sum of agent fee amount and protocol fee amount is greater than fee limit set by seller
     * - Royalty recipient is not on seller's allow list
     * - Royalty percentage is less than the value decided by the admin
     * - Total royalty percentage is more than max royalty percentage
     * - The mutualizer contract does not implement the IDRFeeMutualizer interface
     *
     * @param _offer - the fully populated struct with offer id set to 0x0 and voided set to false
     * @param _offerDates - the fully populated offer dates struct
     * @param _offerDurations - the fully populated offer durations struct
     * @param _drParameters - the id of chosen dispute resolver (can be 0) and mutualizer address (0 for self-mutualization)
     * @param _agentId - the id of agent
     * @param _feeLimit - the maximum fee that seller is willing to pay per exchange (for static offers)
     * @param _authenticate - whether to authenticate the caller. Use false when called from a handler that already authenticated the caller.
     */
    function createOfferInternal(
        Offer memory _offer,
        OfferDates calldata _offerDates,
        OfferDurations calldata _offerDurations,
        BosonTypes.DRParameters calldata _drParameters,
        uint256 _agentId,
        uint256 _feeLimit,
        bool _authenticate
    ) internal returns (uint256 offerId) {
        address sender = _msgSender();

        if (_offer.creator == OfferCreator.Seller) {
            if (_offer.buyerId != 0) revert InvalidBuyerOfferFields();

            // Validate the caller is the seller assistant
            if (_authenticate) {
                (bool isAssistant, uint256 sellerId) = getSellerIdByAssistant(sender);
                if (!isAssistant) {
                    revert NotAssistant();
                }
                _offer.sellerId = sellerId;
            }
        } else if (_offer.creator == OfferCreator.Buyer) {
            if (
                _offer.sellerId != 0 ||
                _offer.collectionIndex != 0 ||
                _offer.royaltyInfo.length != 1 ||
                _offer.royaltyInfo[0].recipients.length != 0 ||
                _offer.royaltyInfo[0].bps.length != 0 ||
                _drParameters.mutualizerAddress != address(0) ||
                _offer.quantityAvailable != 1 ||
                _offer.priceType != PriceType.Static
            ) {
                revert InvalidBuyerOfferFields();
            }
            if (_authenticate) _offer.buyerId = getValidBuyer(payable(sender));
        }

        // Get the next offerId and increment the counter
        offerId = protocolCounters().nextOfferId++;
        _offer.id = offerId;

        // Store the offer
        storeOffer(_offer, _offerDates, _offerDurations, _drParameters, _agentId, _feeLimit);
    }

    /**
     * @notice Validates offer struct and store it to storage.
     *
     * @dev Rationale for the checks that are not obvious:
     * 1. voucher expiration date is either
     *   -  _offerDates.voucherRedeemableUntil  [fixed voucher expiration date]
     *   - max([commitment time], _offerDates.voucherRedeemableFrom) + offerDurations.voucherValid [fixed voucher expiration duration]
     * This is calculated during the commitToOffer. To avoid any ambiguity, we make sure that exactly one of _offerDates.voucherRedeemableUntil
     * and offerDurations.voucherValid is defined.
     * 2. Checks that include _offer.sellerDeposit, protocolFee, offer.buyerCancelPenalty and _offer.price
     * Exchange can have one of multiple final states and different states have different seller and buyer payoffs. If offer parameters are
     * not set appropriately, it's possible for some payoffs to become negative or unfair to some participant. By making the checks at the time
     * of the offer creation we ensure that all payoffs are possible and fair.
     *
     *
     * Reverts if:
     * - Valid from date is greater than valid until date
     * - Valid until date is not in the future
     * - Both fixed voucher expiration date and voucher redemption duration are defined
     * - Neither of fixed voucher expiration date and voucher redemption duration are defined
     * - Voucher redeemable period is fixed, but it ends before it starts
     * - Voucher redeemable period is fixed, but it ends before offer expires
     * - Dispute period is less than minimum dispute period
     * - Resolution period is not between the minimum and the maximum resolution period
     * - Voided is set to true
     * - Available quantity is set to zero
     * - Dispute resolver wallet is not registered, except for absolute zero offers with unspecified dispute resolver
     * - Dispute resolver is not active, except for absolute zero offers with unspecified dispute resolver
     * - Seller is not on dispute resolver's seller allow list
     * - Dispute resolver does not accept fees in the exchange token
     * - Buyer cancel penalty is greater than price
     * - When agent id is non zero:
     *   - If Agent does not exist
     * - If the sum of agent fee amount and protocol fee amount is greater than the offer fee limit determined by the protocol
     * - If the sum of agent fee amount and protocol fee amount is greater than fee limit set by seller
     * - Royalty recipient is not on seller's allow list
     * - Royalty percentage is less than the value decided by the admin
     * - Total royalty percentage is more than max royalty percentage
     * - The mutualizer contract does not implement the IDRFeeMutualizer interface
     *
     * @param _offer - the fully populated struct with offer id set to offer to be updated and voided set to false
     * @param _offerDates - the fully populated offer dates struct
     * @param _offerDurations - the fully populated offer durations struct
     * @param _drParameters - the id of chosen dispute resolver (can be 0) and mutualizer address (0 for self-mutualization)
     * @param _agentId - the id of agent
     * @param _feeLimit - the maximum fee that seller is willing to pay per exchange (for static offers)
     */
    function storeOffer(
        Offer memory _offer,
        OfferDates calldata _offerDates,
        OfferDurations calldata _offerDurations,
        BosonTypes.DRParameters calldata _drParameters,
        uint256 _agentId,
        uint256 _feeLimit
    ) internal {
        // validFrom date must be less than validUntil date
        if (_offerDates.validFrom >= _offerDates.validUntil) revert InvalidOfferPeriod();

        // validUntil date must be in the future
        if (_offerDates.validUntil <= block.timestamp) revert InvalidOfferPeriod();

        // exactly one of voucherRedeemableUntil and voucherValid must be zero
        // if voucherRedeemableUntil exist, it must be greater than validUntil
        if (_offerDates.voucherRedeemableUntil > 0) {
            if (_offerDurations.voucherValid != 0) revert AmbiguousVoucherExpiry();
            if (_offerDates.voucherRedeemableFrom >= _offerDates.voucherRedeemableUntil)
                revert InvalidRedemptionPeriod();
            if (_offerDates.voucherRedeemableUntil < _offerDates.validUntil) revert InvalidRedemptionPeriod();
        } else {
            if (_offerDurations.voucherValid == 0) revert AmbiguousVoucherExpiry();
        }

        // when creating offer, it cannot be set to voided
        if (_offer.voided) revert OfferMustBeActive();

        // quantity must be greater than zero
        if (_offer.quantityAvailable == 0) revert InvalidQuantityAvailable();

        DisputeResolutionTerms memory disputeResolutionTerms;
        OfferFees storage offerFees = fetchOfferFees(_offer.id);
        {
            // Cache protocol lookups for reference
            ProtocolLib.ProtocolLookups storage lookups = protocolLookups();
            ProtocolLib.ProtocolFees storage fees = protocolFees();

            // Specified resolver must be registered and active, except for absolute zero offers with unspecified dispute resolver.
            // If price and sellerDeposit are 0, seller is not obliged to choose dispute resolver, which is done by setting _disputeResolverId to 0.
            // In this case, there is no need to check the validity of the dispute resolver. However, if one (or more) of {price, sellerDeposit, _disputeResolverId}
            // is different from 0, it must be checked that dispute resolver exists, supports the exchange token and seller is allowed to choose them.
            if (_offer.price != 0 || _offer.sellerDeposit != 0 || _drParameters.disputeResolverId != 0) {
                (
                    bool exists,
                    DisputeResolver storage disputeResolver,
                    DisputeResolverFee[] storage disputeResolverFees
                ) = fetchDisputeResolver(_drParameters.disputeResolverId);
                if (!exists || !disputeResolver.active) revert InvalidDisputeResolver();

                // Operate in a block to avoid "stack too deep" error
                {
                    // check that seller is on the DR allow list
                    if (lookups.allowedSellers[_drParameters.disputeResolverId].length > 0) {
                        // if length == 0, dispute resolver allows any seller
                        // if length > 0, we check that it is on allow list
                        if (lookups.allowedSellerIndex[_drParameters.disputeResolverId][_offer.sellerId] == 0)
                            revert SellerNotApproved();
                    }

                    // get the index of DisputeResolverFee and make sure DR supports the exchangeToken
                    {
                        uint256 feeIndex = lookups.disputeResolverFeeTokenIndex[_drParameters.disputeResolverId][
                            _offer.exchangeToken
                        ];
                        if (feeIndex == 0) revert DRUnsupportedFee();

                        uint256 feeAmount = disputeResolverFees[feeIndex - 1].feeAmount;

                        // store DR terms
                        disputeResolutionTerms.disputeResolverId = _drParameters.disputeResolverId;
                        disputeResolutionTerms.escalationResponsePeriod = disputeResolver.escalationResponsePeriod;
                        disputeResolutionTerms.feeAmount = feeAmount;
                        disputeResolutionTerms.buyerEscalationDeposit =
                            (feeAmount * fees.buyerEscalationDepositPercentage) /
                            HUNDRED_PERCENT;
                        disputeResolutionTerms.mutualizerAddress = _drParameters.mutualizerAddress;

                        // Validate mutualizer interface if address is not zero (non-zero means external mutualizer)
                        if (_drParameters.mutualizerAddress != address(0)) {
                            validateMutualizerInterface(_drParameters.mutualizerAddress);
                        }
                    }
                    protocolEntities().disputeResolutionTerms[_offer.id] = disputeResolutionTerms;
                }

                // Collection must exist. Collections with index 0 exist by default.
                if (_offer.collectionIndex > 0) {
                    if (lookups.additionalCollections[_offer.sellerId].length < _offer.collectionIndex)
                        revert NoSuchCollection();
                }
            }
            // Cache protocol limits for reference
            ProtocolLib.ProtocolLimits storage limits = protocolLimits();
            // Operate in a block to avoid "stack too deep" error
            {
                // dispute period must be greater than or equal to the minimum dispute period
                if (_offerDurations.disputePeriod < limits.minDisputePeriod) revert InvalidDisputePeriod();

                // resolution period must be between the minimum and maximum resolution periods
                if (
                    _offerDurations.resolutionPeriod < limits.minResolutionPeriod ||
                    _offerDurations.resolutionPeriod > limits.maxResolutionPeriod
                ) {
                    revert InvalidResolutionPeriod();
                }
            }

            // Operate in a block to avoid "stack too deep" error
            {
                // Get the agent
                (bool agentExists, Agent storage agent) = fetchAgent(_agentId);

                // Make sure agent exists if _agentId is not zero.
                if (_agentId != 0 && !agentExists) revert NoSuchAgent();

                // Set variable to eliminate multiple SLOAD
                uint256 offerPrice = _offer.price;

                // condition for successful payout when exchange final state is canceled
                if (_offer.buyerCancelPenalty > offerPrice) revert InvalidOfferPenalty();
                if (_offer.priceType == PriceType.Static) {
                    // Calculate and set the protocol fee
                    uint256 protocolFee = _getProtocolFee(_offer.exchangeToken, offerPrice);

                    // Calculate the agent fee amount
                    uint256 agentFeeAmount = (agent.feePercentage * offerPrice) / HUNDRED_PERCENT;

                    uint256 totalOfferFeeLimit = (limits.maxTotalOfferFeePercentage * offerPrice) / HUNDRED_PERCENT;

                    // Sum of agent fee amount and protocol fee amount should be <= offer fee limit and less that fee limit set by seller
                    uint256 totalFeeAmount = agentFeeAmount + protocolFee;
                    if (totalFeeAmount > totalOfferFeeLimit) revert AgentFeeAmountTooHigh();
                    if (totalFeeAmount > _feeLimit) revert TotalFeeExceedsLimit();

                    // Set offer fees props individually since calldata structs can't be copied to storage
                    offerFees.protocolFee = protocolFee;
                    offerFees.agentFee = agentFeeAmount;
                }
            }

            // Store the agent id for the offer
            lookups.agentIdByOffer[_offer.id] = _agentId;

            if (_offer.royaltyInfo.length != 1) revert InvalidRoyaltyInfo();
            validateRoyaltyInfo(lookups, limits, _offer.sellerId, _offer.royaltyInfo[0]);
        }
        // Get storage location for offer

        (, Offer storage offer) = fetchOffer(_offer.id);

        // Set offer props individually since memory structs can't be copied to storage
        offer.id = _offer.id;
        offer.sellerId = _offer.sellerId;
        offer.price = _offer.price;
        offer.sellerDeposit = _offer.sellerDeposit;
        offer.buyerCancelPenalty = _offer.buyerCancelPenalty;
        offer.quantityAvailable = _offer.quantityAvailable;
        offer.exchangeToken = _offer.exchangeToken;
        offer.metadataUri = _offer.metadataUri;
        offer.metadataHash = _offer.metadataHash;
        offer.collectionIndex = _offer.collectionIndex;
        offer.priceType = _offer.priceType;
        offer.creator = _offer.creator;
        offer.buyerId = _offer.buyerId;
        offer.royaltyInfo.push(_offer.royaltyInfo[0]);

        // Get storage location for offer dates
        OfferDates storage offerDates = fetchOfferDates(_offer.id);

        // Set offer dates props individually since calldata structs can't be copied to storage
        offerDates.validFrom = _offerDates.validFrom;
        offerDates.validUntil = _offerDates.validUntil;
        offerDates.voucherRedeemableFrom = _offerDates.voucherRedeemableFrom;
        offerDates.voucherRedeemableUntil = _offerDates.voucherRedeemableUntil;

        // Get storage location for offer durations
        OfferDurations storage offerDurations = fetchOfferDurations(_offer.id);

        // Set offer durations props individually since calldata structs can't be copied to storage
        offerDurations.disputePeriod = _offerDurations.disputePeriod;
        offerDurations.voucherValid = _offerDurations.voucherValid;
        offerDurations.resolutionPeriod = _offerDurations.resolutionPeriod;

        // Notify watchers of state change
        emit OfferCreated(
            _offer.id,
            _offer.sellerId,
            _offer,
            _offerDates,
            _offerDurations,
            disputeResolutionTerms,
            offerFees,
            _agentId,
            _msgSender()
        );
    }

    /**
     * @notice Reserves a range of vouchers to be associated with an offer
     *
     * Reverts if:
     * - The offers region of protocol is paused
     * - The exchanges region of protocol is paused
     * - Offer does not exist
     * - Offer already voided
     * - Caller is not the seller
     * - Range length is zero
     * - Range length is greater than quantity available
     * - Range length is greater than maximum allowed range length
     * - Call to BosonVoucher.reserveRange() reverts
     * - _to is not the BosonVoucher contract address or the BosonVoucher contract owner
     *
     * @param _offerId - the id of the offer
     * @param _length - the length of the range
     * @param _to - the address to send the pre-minted vouchers to (contract address or contract owner)
     */
    function reserveRangeInternal(
        uint256 _offerId,
        uint256 _length,
        address _to
    ) internal offersNotPaused exchangesNotPaused {
        // Get offer, make sure the caller is the assistant
        Offer storage offer = getValidOfferWithSellerCheck(_offerId);

        // Invalid ranges:
        // - Empty range
        // - Too large range, since it affects exchangeId
        // - More than quantity available
        if (_length == 0 || _length > type(uint64).max || offer.quantityAvailable < _length)
            revert InvalidRangeLength();

        // Get starting token id
        ProtocolLib.ProtocolCounters storage pc = protocolCounters();
        uint256 _startId = pc.nextExchangeId;

        IBosonVoucher bosonVoucher = IBosonVoucher(
            getCloneAddress(protocolLookups(), offer.sellerId, offer.collectionIndex)
        );

        address sender = _msgSender();

        // _to must be the contract address or the contract owner
        if (_to != address(bosonVoucher) && _to != sender) revert InvalidToAddress();

        // increase exchangeIds
        pc.nextExchangeId = _startId + _length;

        // decrease quantity available, unless offer is unlimited
        if (offer.quantityAvailable != type(uint256).max) {
            offer.quantityAvailable -= _length;
        }

        // Call reserveRange on voucher
        bosonVoucher.reserveRange(_offerId, _startId, _length, _to);

        // Notify external observers
        emit RangeReserved(_offerId, offer.sellerId, _startId, _startId + _length - 1, _to, sender);
    }

    /**
     * @notice Validates that royalty info struct contains valid data
     *
     * Reverts if:
     * - Royalty recipient is not on seller's allow list
     * - Royalty percentage is less than the value decided by the admin
     * - Total royalty percentage is more than max royalty percentage
     *
     * @param _lookups -  the storage pointer to protocol lookups
     * @param _limits - the storage pointer to protocol limits
     * @param _sellerId - the id of the seller
     * @param _royaltyInfo - the royalty info struct
     */
    function validateRoyaltyInfo(
        ProtocolLib.ProtocolLookups storage _lookups,
        ProtocolLib.ProtocolLimits storage _limits,
        uint256 _sellerId,
        RoyaltyInfo memory _royaltyInfo
    ) internal view {
        if (_royaltyInfo.recipients.length != _royaltyInfo.bps.length) revert ArrayLengthMismatch();

        RoyaltyRecipientInfo[] storage royaltyRecipients = _lookups.royaltyRecipientsBySeller[_sellerId];

        uint256 totalRoyalties;
        for (uint256 i = 0; i < _royaltyInfo.recipients.length; ) {
            uint256 royaltyRecipientId;

            if (_royaltyInfo.recipients[i] == address(0)) {
                royaltyRecipientId = 1;
            } else {
                royaltyRecipientId = _lookups.royaltyRecipientIndexBySellerAndRecipient[_sellerId][
                    _royaltyInfo.recipients[i]
                ];
                if (royaltyRecipientId == 0) revert InvalidRoyaltyRecipient();
            }

            if (_royaltyInfo.bps[i] < royaltyRecipients[royaltyRecipientId - 1].minRoyaltyPercentage)
                revert InvalidRoyaltyPercentage();

            totalRoyalties += _royaltyInfo.bps[i];

            unchecked {
                i++;
            }
        }

        if (totalRoyalties > _limits.maxRoyaltyPercentage) revert InvalidRoyaltyPercentage();
    }

    /**
     * @notice Validates that the mutualizer contract implements the IDRFeeMutualizer interface
     *
     * Reverts if:
     * - Call to supportsInterface fails
     * - Call to supportsInterface returns false
     * - Call to supportsInterface returns data of incorrect length
     *
     * @param _mutualizerAddress - the address of the mutualizer contract
     */
    function validateMutualizerInterface(address _mutualizerAddress) internal view {
        (bool success, bytes memory data) = _mutualizerAddress.staticcall(
            abi.encodeWithSelector(IERC165.supportsInterface.selector, type(IDRFeeMutualizer).interfaceId)
        );

        if (!success || data.length != 32 || !abi.decode(data, (bool))) {
            revert UnsupportedMutualizer();
        }
    }

    /**
     * @notice Computes the EIP712 hash of the full offer parameters.
     *
     * @param _fullOffer - the fully populated struct containing offer, offer dates, offer durations, dispute resolution parameters, condition, agent id and fee limit
     * @return - the hash of the complete offer
     */
    function getOfferHashInternal(BosonTypes.FullOffer calldata _fullOffer) internal view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    FULL_OFFER_TYPEHASH,
                    hashOffer(_fullOffer.offer),
                    keccak256(abi.encode(OFFER_DATES_TYPEHASH, _fullOffer.offerDates)),
                    keccak256(abi.encode(OFFER_DURATIONS_TYPEHASH, _fullOffer.offerDurations)),
                    keccak256(abi.encode(DR_PARAMETERS_TYPEHASH, _fullOffer.drParameters)),
                    keccak256(abi.encode(CONDITION_TYPEHASH, _fullOffer.condition)),
                    _fullOffer.agentId,
                    _fullOffer.feeLimit,
                    _fullOffer.useDepositedFunds
                )
            );
    }

    /**
     * @notice Hashes the modified offer struct for EIP712.
     *
     * It does not include the id, priceType, quantityAvailable since they are constant and validated elsewhere.
     * RoyaltyInfo is also simplified to a single recipients and bps list (this is also enforced in createOfferInternal).
     *
     * @param _offer - the offer to hash
     * @return - the hash of the offer
     */
    function hashOffer(BosonTypes.Offer memory _offer) internal view returns (bytes32) {
        return
            keccak256(
                abi.encode(
                    OFFER_TYPEHASH,
                    _offer.sellerId,
                    _offer.price,
                    _offer.sellerDeposit,
                    _offer.buyerCancelPenalty,
                    _offer.quantityAvailable,
                    _offer.exchangeToken,
                    keccak256(bytes(_offer.metadataUri)),
                    keccak256(bytes(_offer.metadataHash)),
                    _offer.collectionIndex,
                    keccak256(
                        abi.encode(
                            ROYALTY_INFO_TYPEHASH,
                            keccak256(abi.encodePacked(_offer.royaltyInfo[0].recipients)),
                            keccak256(abi.encodePacked(_offer.royaltyInfo[0].bps))
                        )
                    ),
                    _offer.creator,
                    _offer.buyerId
                )
            );
    }
}

contracts/protocol/bases/PausableBase.so.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import "./../../domain/BosonConstants.sol";
import { BosonErrors } from "../../domain/BosonErrors.sol";
import { ProtocolLib } from "../libs/ProtocolLib.sol";
import { BosonTypes } from "../../domain/BosonTypes.sol";

/**
 * @title PausableBase
 *
 * @notice Provides modifiers for regional pausing
 */
contract PausableBase is BosonTypes {
    /**
     * @notice Modifier that checks the Offers region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier offersNotPaused() {
        revertIfPaused(PausableRegion.Offers);
        _;
    }

    /**
     * @notice Modifier that checks the Twins region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier twinsNotPaused() {
        revertIfPaused(PausableRegion.Twins);
        _;
    }

    /**
     * @notice Modifier that checks the Bundles region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier bundlesNotPaused() {
        revertIfPaused(PausableRegion.Bundles);
        _;
    }

    /**
     * @notice Modifier that checks the Groups region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier groupsNotPaused() {
        revertIfPaused(PausableRegion.Groups);
        _;
    }

    /**
     * @notice Modifier that checks the Sellers region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier sellersNotPaused() {
        revertIfPaused(PausableRegion.Sellers);
        _;
    }

    /**
     * @notice Modifier that checks the Buyers region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier buyersNotPaused() {
        revertIfPaused(PausableRegion.Buyers);
        _;
    }

    /**
     * @notice Modifier that checks the Agents region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier agentsNotPaused() {
        revertIfPaused(PausableRegion.Agents);
        _;
    }

    /**
     * @notice Modifier that checks the DisputeResolvers region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier disputeResolversNotPaused() {
        revertIfPaused(PausableRegion.DisputeResolvers);
        _;
    }

    /**
     * @notice Modifier that checks the Exchanges region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier exchangesNotPaused() {
        revertIfPaused(PausableRegion.Exchanges);
        _;
    }

    /**
     * @notice Modifier that checks the Disputes region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier disputesNotPaused() {
        revertIfPaused(PausableRegion.Disputes);
        _;
    }

    /**
     * @notice Modifier that checks the Funds region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier fundsNotPaused() {
        revertIfPaused(PausableRegion.Funds);
        _;
    }

    /**
     * @notice Modifier that checks the Orchestration region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier orchestrationNotPaused() {
        revertIfPaused(PausableRegion.Orchestration);
        _;
    }

    /**
     * @notice Modifier that checks the MetaTransaction region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier metaTransactionsNotPaused() {
        revertIfPaused(PausableRegion.MetaTransaction);
        _;
    }

    /**
     * @notice Modifier that checks the PriceDiscovery region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier priceDiscoveryNotPaused() {
        revertIfPaused(PausableRegion.PriceDiscovery);
        _;
    }

    /**
     * @notice Modifier that checks the SequentialCommit region is not paused
     *
     * Reverts if region is paused
     *
     * See: {BosonTypes.PausableRegion}
     */
    modifier sequentialCommitNotPaused() {
        revertIfPaused(PausableRegion.SequentialCommit);
        _;
    }

    /**
     * @notice Checks if a region of the protocol is paused.
     *
     * Reverts if region is paused
     *
     * @param _region the region to check pause status for
     */
    function revertIfPaused(PausableRegion _region) internal view {
        // Region enum value must be used as the exponent in a power of 2
        uint256 powerOfTwo = 1 << uint256(_region);
        if ((ProtocolLib.protocolStatus().pauseScenario & powerOfTwo) == powerOfTwo)
            revert BosonErrors.RegionPaused(_region);
    }
}

contracts/protocol/bases/ProtocolBase.so.content:
// SPDX-License-Identifier: GPL-3.0-or-later
pragma solidity 0.8.35;

import "../../domain/BosonConstants.sol";
